import React, { createContext, useContext, useEffect, useState } from 'react';
import { useQuery } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { Id } from '../../convex/_generated/dataModel';

interface User {
    _id: Id<"users">;
    email: string;
    name: string;
    phone: string;
    network: "MTN" | "Glo" | "Airtel" | "9Mobile" | "Unknown";
    role: "admin" | "member" | "super_admin" | "board_member";
    whatsappVerified: boolean;
    avatarUrl?: string;
    coverImageUrl?: string;
    profession?: string;
    gender?: string;
    showPostViews?: boolean;
    bankDetails?: {
        bankName: string;
        accountNumber: string;
        accountName: string;
    };
    createdAt: number;
    chatWallpaperUrl?: string;
    lastViewedBanking?: number;
    lastViewedLeaderboard?: number;
    lastViewedMessages?: number;
    lastViewedCommunityChatAt?: number;
    lastViewedNotifications?: number;
}

interface AuthContextType {
    user: User | null;
    isLoading: boolean;
    login: (user: User) => void;
    logout: () => void;
    updateUser: (updates: Partial<User>) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const AUTH_STORAGE_KEY = 'baptizo-auth-user';

export function AuthProvider({ children }: { children: React.ReactNode }) {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    // Load user from localStorage on mount
    useEffect(() => {
        const stored = localStorage.getItem(AUTH_STORAGE_KEY);
        if (stored) {
            try {
                const parsedUser = JSON.parse(stored);
                // Guard: Convex IDs are alphanumeric strings. If the stored _id
                // somehow belongs to another table (e.g. a meetings ID was saved
                // by mistake), clear storage and force re-login rather than crashing.
                if (!parsedUser?._id || typeof parsedUser._id !== 'string') {
                    console.warn('Corrupt auth session detected (missing _id). Clearing.');
                    localStorage.removeItem(AUTH_STORAGE_KEY);
                } else {
                    setUser(parsedUser);
                }
            } catch (error) {
                console.error('Failed to parse stored user:', error);
                localStorage.removeItem(AUTH_STORAGE_KEY);
            }
        }
        setIsLoading(false);
    }, []);

    // Fetch fresh user data from DB to ensure roles/data are in sync.
    // Pass 'skip' if no user is loaded yet, or if the stored ID looks suspicious
    // (Convex will throw an ArgumentValidationError if the ID belongs to another table).
    const freshUser = useQuery(
        api.users.getUser,
        user?._id ? { userId: user._id } : 'skip'
    );

    // Sync fresh DB data with local state.
    // If freshUser is explicitly null (not undefined/loading), the DB returned no match
    // for the stored ID — auto-logout to prevent a permanent crash loop.
    useEffect(() => {
        if (freshUser === null && user) {
            console.warn('Session user not found in DB. Clearing stale session.');
            localStorage.removeItem(AUTH_STORAGE_KEY);
            setUser(null);
            return;
        }
        if (freshUser && user) {
            // Check if important fields changed (e.g. role update or unread status)
            const hasChanged =
                freshUser.role !== user.role ||
                freshUser.name !== user.name ||
                freshUser.avatarUrl !== user.avatarUrl ||
                freshUser.coverImageUrl !== user.coverImageUrl ||
                freshUser.lastViewedCommunityChatAt !== (user as any).lastViewedCommunityChatAt ||
                freshUser.lastViewedBanking !== (user as any).lastViewedBanking ||
                freshUser.lastViewedLeaderboard !== (user as any).lastViewedLeaderboard ||
                freshUser.lastViewedNotifications !== (user as any).lastViewedNotifications;

            if (hasChanged) {
                const updatedUser = { ...user, ...freshUser };
                setUser(updatedUser);
            }
        }
    }, [freshUser, user]);

    // Save user to localStorage whenever it changes
    useEffect(() => {
        if (isLoading) return; // Wait for initial mount/load to finish

        if (user) {
            localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(user));
        } else {
            localStorage.removeItem(AUTH_STORAGE_KEY);
        }
    }, [user, isLoading]);

    const login = (newUser: User) => {
        setUser(newUser);
    };

    const logout = () => {
        setUser(null);
    };

    const updateUser = (updates: Partial<User>) => {
        if (user) {
            setUser({ ...user, ...updates });
        }
    };

    return (
        <AuthContext.Provider value={{ user, isLoading, login, logout, updateUser }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}
