import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Loader2 } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { Avatar } from '@/components/ui/Avatar';

interface Props {
    reactingMsg: { id: any; isGroup: boolean } | null;
    onClose: () => void;
}

export function ReactionDetailsModal({ reactingMsg, onClose }: Props) {
    const reactionDetails = useQuery(
        api.chat.getReactionDetails,
        reactingMsg ? { messageId: reactingMsg.id, isGroup: reactingMsg.isGroup } : 'skip'
    );

    if (!reactingMsg) return null;

    return (
        <AnimatePresence>
            <motion.div
                key="reaction-backdrop"
                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center p-4"
                onClick={onClose}
            >
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
                <motion.div
                    initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 100, opacity: 0 }}
                    className="relative z-10 w-full max-w-sm bg-white dark:bg-gray-900 rounded-3xl shadow-2xl overflow-hidden"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-gray-800">
                        <h3 className="font-bold text-gray-900 dark:text-gray-100 italic">Reactions</h3>
                        <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors">
                            <X className="w-5 h-5 text-gray-500" />
                        </button>
                    </div>
                    <div className="max-h-[60vh] overflow-y-auto">
                        {!reactionDetails ? (
                            <div className="flex items-center justify-center py-12">
                                <Loader2 className="w-8 h-8 animate-spin text-primary-500" />
                            </div>
                        ) : reactionDetails.length === 0 ? (
                            <div className="py-12 text-center text-gray-500 italic">No reactions yet</div>
                        ) : (
                            <div className="divide-y divide-gray-50 dark:divide-gray-800">
                                {reactionDetails.map((r: any, idx: number) => (
                                    <div key={idx} className="flex items-center gap-3 px-6 py-4 hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                                        <div className="relative">
                                            <Avatar src={r.avatarUrl} alt={r.name} className="w-10 h-10 border-2 border-primary-500/20" />
                                            <span className="absolute -bottom-1 -right-1 bg-white dark:bg-gray-800 rounded-full shadow-sm text-xs w-5 h-5 flex items-center justify-center border border-gray-100 dark:border-gray-700">
                                                {r.emoji}
                                            </span>
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <p className="font-bold text-gray-900 dark:text-gray-100">{r.name}</p>
                                            <p className="text-[10px] text-primary-500 font-medium">
                                                {formatDistanceToNow(r.createdAt, { addSuffix: true })}
                                            </p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </motion.div>
            </motion.div>
        </AnimatePresence>
    );
}
