import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useMutation } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Mail, ArrowLeft, Send, CheckCircle2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export function ForgotPassword() {
    const requestReset = useMutation(api.passwordReset.requestReset);
    const [email, setEmail] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitted, setIsSubmitted] = useState(false);
    const [error, setError] = useState('');
    const [resetLink, setResetLink] = useState(''); // FOR DEMO: Show the link

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            const result = await requestReset({ email: email.toLowerCase().trim() });
            if (result.success) {
                setIsSubmitted(true);
                // FOR DEMO: If token is returned, construct the link
                if (result.token) {
                    const link = `${window.location.origin}/reset-password?token=${result.token}`;
                    setResetLink(link);
                    console.log("Reset Link:", link);
                }
            }
        } catch (err: any) {
            setError(err.message || "Failed to request reset");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="w-full max-w-md mx-auto"
            >
                <Card glass>
                    <CardHeader className="pt-8 pt-6">
                        <Link
                            to="/login"
                            className="flex items-center gap-2 text-sm text-light-muted dark:text-dark-muted hover:text-primary-500 transition-colors mb-4 w-fit"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Back to Login
                        </Link>
                        <CardTitle className="text-2xl font-bold">Forgot Password?</CardTitle>
                        <p className="text-light-muted dark:text-dark-muted mt-2">
                            Enter your email and we'll send you a link to reset your password.
                        </p>
                    </CardHeader>
                    <CardContent className="pb-8">
                        <AnimatePresence mode="wait">
                            {!isSubmitted ? (
                                <motion.form
                                    key="form"
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    exit={{ opacity: 0 }}
                                    onSubmit={handleSubmit}
                                    className="space-y-4"
                                >
                                    {error && (
                                        <div className="p-3 rounded-lg bg-red-50 dark:bg-red-950 border border-red-200 dark:border-red-800 text-sm text-red-600 dark:text-red-400">
                                            {error}
                                        </div>
                                    )}

                                    <Input
                                        label="Email Address"
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        icon={<Mail className="w-5 h-5" />}
                                        placeholder="your@email.com"
                                        required
                                        autoFocus
                                    />

                                    <Button
                                        type="submit"
                                        variant="primary"
                                        className="w-full h-12"
                                        isLoading={isLoading}
                                    >
                                        <Send className="w-4 h-4 mr-2" />
                                        Send Reset Link
                                    </Button>
                                </motion.form>
                            ) : (
                                <motion.div
                                    key="success"
                                    initial={{ opacity: 0, scale: 0.95 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    className="text-center py-4"
                                >
                                    <div className="w-16 h-16 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
                                        <CheckCircle2 className="w-8 h-8 text-green-600 dark:text-green-400" />
                                    </div>
                                    <h3 className="text-xl font-bold mb-2">Check your inbox</h3>
                                    <p className="text-light-muted dark:text-dark-muted mb-6">
                                        We've sent a password reset link to <span className="font-semibold text-gray-900 dark:text-white">{email}</span>.
                                    </p>

                                    {/* DEMO FALLBACK: Since we don't have an email provider */}
                                    {resetLink && (
                                        <div className="p-4 bg-primary-50 dark:bg-primary-900/10 border border-primary-100 dark:border-primary-900/30 rounded-2xl mb-6">
                                            <p className="text-xs font-semibold text-primary-600 dark:text-primary-400 uppercase tracking-wider mb-2">
                                                Developer Preview Link (No Email Provider Configured)
                                            </p>
                                            <Link
                                                to={resetLink.replace(window.location.origin, '')}
                                                className="text-sm font-medium text-primary-500 break-all underline"
                                            >
                                                {resetLink}
                                            </Link>
                                        </div>
                                    )}

                                    <Button
                                        variant="outline"
                                        className="w-full"
                                        onClick={() => setIsSubmitted(false)}
                                    >
                                        Didn't receive it? Try again
                                    </Button>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </CardContent>
                </Card>
            </motion.div>
        </div>
    );
}
