import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/Button';
import { redirectToWhatsAppGroup } from '@/utils/whatsapp';
import { motion } from 'framer-motion';
import { Check } from 'lucide-react';

export function MemberOnboarding() {
    const { user, isLoading: authLoading } = useAuth();
    const location = useLocation();
    const navigate = useNavigate();

    // Wait for auth to load
    if (authLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-500" />
            </div>
        );
    }

    // Redirect if not logged in
    if (!user) {
        return <Navigate to="/login" state={{ from: location }} replace />;
    }

    const handleWhatsAppRedirect = () => {
        redirectToWhatsAppGroup();
        setTimeout(() => {
            const from = (location.state as any)?.from?.pathname || '/feed';
            navigate(from, { replace: true });
        }, 1000);
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-white dark:bg-[#0A0A0A]"
        >
            <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-50">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-primary-500/10 rounded-full blur-[120px] -translate-y-1/2 translate-x-1/2" />
                <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-secondary-500/10 rounded-full blur-[120px] translate-y-1/2 -translate-x-1/2" />
            </div>

            <motion.div
                initial={{ scale: 0.9, opacity: 0, y: 20 }}
                animate={{ scale: 1, opacity: 1, y: 0 }}
                transition={{ type: "spring", damping: 25, stiffness: 200 }}
                className="relative w-full max-w-md bg-white dark:bg-[#151515] border border-light-border dark:border-dark-border shadow-2xl rounded-[2.5rem] p-6 sm:p-10 text-center"
            >
                <div className="flex justify-center mb-6">
                    <img
                        src="https://ik.imagekit.io/h3qzmviwv/baptizo/Logo/premium-logo.png"
                        alt="Baptizo"
                        className="h-16 w-auto rounded-2xl shadow-xl shadow-primary-500/10"
                    />
                </div>

                <motion.div
                    initial={{ scale: 0, rotate: -20 }}
                    animate={{ scale: 1, rotate: 0 }}
                    transition={{ delay: 0.2, type: "spring", damping: 15 }}
                    className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-gradient-to-br from-primary-500 to-primary-700 flex items-center justify-center shadow-lg shadow-primary-500/30"
                >
                    <Check className="w-10 h-10 text-white" />
                </motion.div>

                <h2 className="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white mb-3 tracking-tight">
                    Welcome Aboard!
                </h2>

                <p className="text-base text-light-muted dark:text-dark-muted mb-8 leading-relaxed px-2">
                    Your journey with Baptizo Community begins now. We're thrilled to have you here {user.name.split(' ')[0]}.
                </p>

                <div className="space-y-6">
                    <div className="relative group overflow-hidden bg-emerald-50/50 dark:bg-emerald-900/10 p-5 rounded-3xl border border-emerald-100 dark:border-emerald-900/30 transition-all">
                        <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:scale-110 transition-transform">
                            <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" alt="" className="w-12 h-12" />
                        </div>
                        <h3 className="font-bold text-emerald-800 dark:text-emerald-400 mb-2 flex items-center justify-center gap-2">
                            <span className="relative flex h-3 w-3">
                                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                                <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
                            </span>
                            Final Step: Join the Community
                        </h3>
                        <p className="text-sm text-emerald-700/80 dark:text-emerald-300/70">
                            Connect with other members and get real-time updates in our exclusive WhatsApp group.
                        </p>
                    </div>

                    <div className="space-y-3">
                        <Button
                            onClick={handleWhatsAppRedirect}
                            className="w-full h-14 text-lg font-semibold bg-[#25D366] hover:bg-[#128C7E] text-white rounded-2xl shadow-xl shadow-green-500/20 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
                        >
                            <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" alt="" className="w-6 h-6 contrast-125" />
                            Join WhatsApp Group
                        </Button>

                        <button
                            onClick={() => navigate('/feed')}
                            className="w-full py-3 text-sm font-medium text-light-muted dark:text-dark-muted hover:text-primary-500 transition-colors"
                        >
                            Skip for now &amp; Go to Feed
                        </button>
                    </div>
                </div>
            </motion.div>
        </motion.div>
    );
}
