import { ArrowLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface BackButtonProps {
    to?: string;
    label?: string;
}

export function BackButton({ to = '/feed', label = 'Back to Feed' }: BackButtonProps) {
    const navigate = useNavigate();

    return (
        <button
            onClick={() => navigate(to)}
            className="flex items-center gap-2 text-primary-500 hover:text-primary-600 transition-colors text-sm font-bold group"
        >
            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
            {label}
        </button>
    );
}
