import { useState, useRef, useEffect } from 'react';
import { Play, Pause, Volume2, VolumeX } from 'lucide-react';
import { motion } from 'framer-motion';

interface AudioPlayerProps {
    url: string;
    duration?: number;
}

export function AudioPlayer({ url, duration = 0 }: AudioPlayerProps) {
    const [isPlaying, setIsPlaying] = useState(false);
    const [currentTime, setCurrentTime] = useState(0);
    const [isMuted, setIsMuted] = useState(false);
    const audioRef = useRef<HTMLAudioElement>(null);
    const progressBarRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const audio = audioRef.current;
        if (!audio) return;

        const updateTime = () => setCurrentTime(audio.currentTime);
        const handleEnded = () => {
            setIsPlaying(false);
            setCurrentTime(0);
        };

        audio.addEventListener('timeupdate', updateTime);
        audio.addEventListener('ended', handleEnded);

        return () => {
            audio.removeEventListener('timeupdate', updateTime);
            audio.removeEventListener('ended', handleEnded);
        };
    }, []);

    const togglePlay = () => {
        if (!audioRef.current) return;
        if (isPlaying) {
            audioRef.current.pause();
        } else {
            audioRef.current.play();
        }
        setIsPlaying(!isPlaying);
    };

    const toggleMute = () => {
        if (!audioRef.current) return;
        audioRef.current.muted = !isMuted;
        setIsMuted(!isMuted);
    };

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    const handleSeek = (e: React.MouseEvent<HTMLDivElement>) => {
        if (!audioRef.current || !progressBarRef.current) return;

        const rect = progressBarRef.current.getBoundingClientRect();
        const percent = (e.clientX - rect.left) / rect.width;

        // Use supplied total duration if audio metadata isn't fully loaded
        const targetTime = percent * (audioRef.current.duration || duration);
        audioRef.current.currentTime = targetTime;
        setCurrentTime(targetTime);
    };

    // Calculate progress based on either actual playing time against known duration, 
    // or using the passed duration prop as a fallback before load
    const actualDuration = audioRef.current?.duration || duration;
    const progressPercent = actualDuration > 0 ? (currentTime / actualDuration) * 100 : 0;

    return (
        <div
            onClick={(e) => e.stopPropagation()}
            className="w-full bg-gray-50 dark:bg-[#252525] border border-gray-100 dark:border-gray-800 rounded-2xl p-4 my-3"
        >
            <div className="flex items-center gap-4">
                {/* Play/Pause Button */}
                <button
                    onClick={togglePlay}
                    className="w-12 h-12 rounded-full bg-primary-500 hover:bg-primary-600 text-white flex items-center justify-center shadow-md transition-transform hover:scale-105 shrink-0"
                >
                    {isPlaying ? (
                        <Pause className="w-5 h-5 fill-current" />
                    ) : (
                        <Play className="w-5 h-5 fill-current ml-1" />
                    )}
                </button>

                {/* Progress Controls */}
                <div className="flex-1 min-w-0">
                    <div
                        ref={progressBarRef}
                        className="h-2 bg-gray-200 dark:bg-gray-700 rounded-full cursor-pointer relative mb-1.5"
                        onClick={handleSeek}
                    >
                        <motion.div
                            className="absolute top-0 left-0 h-full bg-primary-500 rounded-full"
                            style={{ width: `${progressPercent}%` }}
                            transition={{ ease: "linear", duration: 0.1 }}
                        />
                        {/* Playhead thumb */}
                        <div
                            className="absolute top-1/2 -mt-1.5 w-3 h-3 bg-white border-2 border-primary-500 rounded-full shadow-sm"
                            style={{ left: `calc(${progressPercent}% - 6px)` }}
                        />
                    </div>

                    <div className="flex items-center justify-between text-xs font-medium text-gray-500 dark:text-gray-400">
                        <span>{formatTime(currentTime)}</span>
                        <span>{formatTime(actualDuration)}</span>
                    </div>
                </div>

                {/* Volume Toggle */}
                <button
                    onClick={toggleMute}
                    className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 transition-colors shrink-0"
                >
                    {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                </button>
            </div>

            <audio
                ref={audioRef}
                src={url}
                preload="none"
                className="hidden"
            />
        </div>
    );
}
