import { useState } from 'react';
import { Image as ImageIcon } from 'lucide-react';

export function ChatImage({ src, alt }: { src: string; alt: string }) {
    const [isLoaded, setIsLoaded] = useState(false);
    return (
        <div className="relative rounded-lg overflow-hidden mb-2 bg-gray-100 dark:bg-gray-700 min-h-[150px] min-w-[200px] flex items-center justify-center">
            {!isLoaded && (
                <div className="absolute inset-0 animate-pulse bg-gray-200 dark:bg-gray-800 flex items-center justify-center">
                    <ImageIcon className="w-8 h-8 text-gray-400 opacity-50" />
                </div>
            )}
            <img
                src={src}
                alt={alt}
                className={`max-w-full max-h-[300px] object-cover transition-opacity duration-300 ${isLoaded ? 'opacity-100' : 'opacity-0'}`}
                onLoad={() => setIsLoaded(true)}
            />
        </div>
    );
}
