import { useState, useRef, useEffect } from "react";
import { Mic, Square, Play, Pause, Trash2, X } from "lucide-react";
import { Button } from "../ui/Button";

interface AudioRecorderProps {
    onRecordingComplete: (audioBlob: Blob, duration: number) => void;
    onCancel: () => void;
}

const MAX_RECORDING_TIME = 300; // 5 minutes in seconds

export function AudioRecorder({ onRecordingComplete, onCancel }: AudioRecorderProps) {
    const [isRecording, setIsRecording] = useState(false);
    const [recordingTime, setRecordingTime] = useState(0);
    const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
    const [audioUrl, setAudioUrl] = useState<string | null>(null);
    const [isPlaying, setIsPlaying] = useState(false);
    const [previewTime, setPreviewTime] = useState(0);

    const mediaRecorder = useRef<MediaRecorder | null>(null);
    const audioChunks = useRef<Blob[]>([]);
    const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const audioPlayerRef = useRef<HTMLAudioElement | null>(null);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
            if (mediaRecorder.current && mediaRecorder.current.state === "recording") {
                mediaRecorder.current.stop();
            }
        };
    }, []);

    // Stop recording if max time reached
    useEffect(() => {
        if (recordingTime >= MAX_RECORDING_TIME && isRecording) {
            stopRecording();
        }
    }, [recordingTime, isRecording]);

    // Cleanup and memoize audio URL payload to stop render loops
    useEffect(() => {
        if (audioBlob) {
            const url = URL.createObjectURL(audioBlob);
            setAudioUrl(url);
            return () => URL.revokeObjectURL(url);
        } else {
            setAudioUrl(null);
        }
    }, [audioBlob]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${mins}:${secs.toString().padStart(2, "0")}`;
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const recorder = new MediaRecorder(stream, {
                // Try to use a widely supported lightweight format, fallback if unsupported
                mimeType: MediaRecorder.isTypeSupported("audio/webm") ? "audio/webm" : "audio/mp4"
            });

            audioChunks.current = [];
            recorder.ondataavailable = (e) => {
                if (e.data.size > 0) audioChunks.current.push(e.data);
            };

            recorder.onstop = () => {
                const audioType = recorder.mimeType || "audio/webm";
                const blob = new Blob(audioChunks.current, { type: audioType });
                setAudioBlob(blob);

                // Clean up tracks to release microphone
                stream.getTracks().forEach(track => track.stop());
            };

            mediaRecorder.current = recorder;
            recorder.start(100);
            setIsRecording(true);
            setRecordingTime(0);

            timerRef.current = setInterval(() => {
                setRecordingTime((prev) => prev + 1);
            }, 1000);
        } catch (err) {
            console.error("Error accessing microphone:", err);
            alert("Please allow microphone access to record audio.");
        }
    };

    const stopRecording = () => {
        if (mediaRecorder.current && mediaRecorder.current.state === "recording") {
            mediaRecorder.current.stop();
            setIsRecording(false);
            if (timerRef.current) clearInterval(timerRef.current);
        }
    };

    const handleConfirm = () => {
        if (audioBlob) {
            onRecordingComplete(audioBlob, recordingTime);
        }
    };

    const togglePreview = () => {
        if (!audioPlayerRef.current) return;

        if (isPlaying) {
            audioPlayerRef.current.pause();
        } else {
            audioPlayerRef.current.play();
        }
        setIsPlaying(!isPlaying);
    };

    const handleTimeUpdate = () => {
        if (audioPlayerRef.current) {
            setPreviewTime(audioPlayerRef.current.currentTime);
        }
    };

    const handleEnded = () => {
        setIsPlaying(false);
        setPreviewTime(0);
    };

    const getProgressWidth = () => {
        // either record-time progress out of max, or playback progress out of recorded length
        if (isRecording) {
            return `${(recordingTime / MAX_RECORDING_TIME) * 100}%`;
        }
        if (audioBlob && recordingTime > 0) {
            return `${(previewTime / recordingTime) * 100}%`;
        }
        return "0%";
    };

    return (
        <div className="bg-gray-50 dark:bg-[#1A1A1A] border border-gray-200 dark:border-gray-800 rounded-2xl p-4 md:p-6 w-full relative">
            <button
                onClick={onCancel}
                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
            >
                <X className="w-5 h-5" />
            </button>

            <div className="flex flex-col items-center justify-center space-y-6">
                {/* Audio Visual Component State */}
                <div className="flex flex-col items-center space-y-2">
                    <div className={`text-4xl font-display font-light tracking-widest ${isRecording ? 'text-red-500 animate-pulse' : 'text-gray-800 dark:text-gray-200'}`}>
                        {formatTime(isRecording ? recordingTime : (audioBlob ? previewTime : 0))}
                    </div>
                    {audioBlob && !isRecording && (
                        <div className="text-xs text-gray-500 font-medium tracking-wide uppercase">
                            Total: {formatTime(recordingTime)}
                        </div>
                    )}
                </div>

                {/* Progress Bar Display */}
                <div className="w-full max-w-sm h-2 bg-gray-200 dark:bg-gray-800 rounded-full overflow-hidden">
                    <div
                        className={`h-full transition-all duration-300 ${isRecording ? 'bg-red-500' : 'bg-primary-500'}`}
                        style={{ width: getProgressWidth() }}
                    />
                </div>

                {/* Controls Area */}
                <div className="flex items-center gap-4">
                    {!audioBlob && !isRecording && (
                        <button
                            onClick={startRecording}
                            className="w-16 h-16 rounded-full bg-red-500 hover:bg-red-600 shadow-lg shadow-red-500/30 text-white flex items-center justify-center transition-transform hover:scale-105"
                        >
                            <Mic className="w-8 h-8" />
                        </button>
                    )}

                    {isRecording && (
                        <button
                            onClick={stopRecording}
                            className="w-16 h-16 rounded-full bg-red-50 text-red-500 border-2 border-red-500 hover:bg-red-100 dark:bg-red-900/20 dark:hover:bg-red-900/40 flex items-center justify-center transition-transform hover:scale-105"
                        >
                            <Square className="w-6 h-6 fill-current" />
                        </button>
                    )}

                    {audioBlob && !isRecording && (
                        <>
                            <button
                                onClick={() => {
                                    setAudioBlob(null);
                                    setRecordingTime(0);
                                    setPreviewTime(0);
                                    setIsPlaying(false);
                                }}
                                className="w-12 h-12 rounded-full bg-gray-200 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-300 dark:hover:bg-gray-700 flex items-center justify-center transition-transform hover:scale-105"
                                title="Discard"
                            >
                                <Trash2 className="w-5 h-5" />
                            </button>

                            <button
                                onClick={togglePreview}
                                className="w-16 h-16 rounded-full bg-primary-500 text-white hover:bg-primary-600 shadow-lg shadow-primary-500/30 flex items-center justify-center transition-transform hover:scale-105 ml-2 mr-2"
                            >
                                {isPlaying ? <Pause className="w-8 h-8 fill-current" /> : <Play className="w-8 h-8 fill-current ml-1" />}
                            </button>

                            <Button
                                onClick={handleConfirm}
                                className="h-12 px-6 rounded-full font-bold shadow-lg shadow-primary-500/20"
                            >
                                Attach
                            </Button>

                            {/* Hidden audio element for preview */}
                            {audioUrl && (
                                <audio
                                    ref={audioPlayerRef}
                                    src={audioUrl}
                                    onTimeUpdate={handleTimeUpdate}
                                    onEnded={handleEnded}
                                    className="hidden"
                                />
                            )}
                        </>
                    )}
                </div>

                {(!audioBlob && !isRecording) && (
                    <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">
                        Click to start recording (Max 5 minutes)
                    </p>
                )}
            </div>
        </div>
    );
}
