import { motion } from 'framer-motion';
import { Avatar } from './Avatar';
import { X, Shield, Loader2 } from 'lucide-react';
import { Link } from 'react-router-dom';
import { Id } from '../../../convex/_generated/dataModel';

interface UserListItem {
    _id: Id<"users">;
    name: string;
    role: 'admin' | 'member' | 'super_admin' | 'board_member';
    avatarUrl?: string;
}

interface UserListModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    users?: UserListItem[];
}

export function UserListModal({ isOpen, onClose, title, users }: UserListModalProps) {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center sm:p-4 px-4">
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 bg-black/60 backdrop-blur-sm"
                onClick={onClose}
            />

            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                className="relative bg-white dark:bg-[#1A1A1A] w-full max-w-sm rounded-[2rem] sm:rounded-3xl shadow-2xl overflow-hidden border border-gray-100/50 dark:border-gray-800/50 flex flex-col max-h-[80vh]"
            >
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-gray-100 dark:border-gray-800">
                    <h2 className="text-xl font-bold font-display text-gray-900 dark:text-white capitalize">
                        {title}
                    </h2>
                    <button
                        onClick={onClose}
                        className="p-2 -mr-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Content Area */}
                <div className="overflow-y-auto p-2">
                    {users === undefined ? (
                        <div className="p-8 flex justify-center items-center text-gray-500">
                            <Loader2 className="w-6 h-6 animate-spin" />
                        </div>
                    ) : users.length === 0 ? (
                        <div className="p-8 text-center text-gray-500 dark:text-gray-400">
                            No one to show yet.
                        </div>
                    ) : (
                        <div className="space-y-1">
                            {users.map((user) => {
                                const isOfficial = user.role === 'admin' || user.role === 'super_admin';

                                return (
                                    <Link
                                        key={user._id}
                                        to={`/profile/${user._id}`}
                                        className="flex items-center gap-3 p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-colors"
                                    >
                                        <div className="relative">
                                            <Avatar
                                                src={user.avatarUrl}
                                                alt={user.name}
                                                className={`w-10 h-10 ring-2 ${isOfficial
                                                    ? 'ring-primary-500'
                                                    : 'ring-transparent'
                                                    }`}
                                            />
                                            {isOfficial && (
                                                <div className="absolute -bottom-1 -right-1 bg-primary-500 text-white p-0.5 rounded-full ring-2 ring-white dark:ring-[#1A1A1A]">
                                                    <Shield className="w-3 h-3" />
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="font-semibold text-gray-900 dark:text-gray-100 text-sm">
                                                {user.name}
                                            </span>
                                            <span className="text-xs text-gray-500 dark:text-gray-400">
                                                {isOfficial ? 'Admin' : 'Member'}
                                            </span>
                                        </div>
                                    </Link>
                                );
                            })}
                        </div>
                    )}
                </div>
            </motion.div>
        </div>
    );
}
