import { useState } from 'react';
import { useMutation, useAction, useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/Button';
import { MediaUpload } from '@/components/ui/MediaUpload';
import { AudioRecorder } from './AudioRecorder';
import { motion } from 'framer-motion';
import { Sparkles } from 'lucide-react';

interface PostFormProps {
    onSuccess?: (postId?: string) => void;
    defaultCategory?: 'Ancient Culture' | 'Wisdom of The Now';
    variant?: 'default' | 'bottom-sheet';
    postType?: 'general' | 'question' | 'prayer';
}

export function PostForm({ onSuccess, defaultCategory, variant = 'default', postType }: PostFormProps) {
    const { user } = useAuth();
    const createPost = useMutation(api.posts.createPost);

    const [content, setContent] = useState('');
    const [activeType, setActiveType] = useState<'Ancient Culture' | 'Wisdom of The Now' | 'question' | 'prayer'>(
        (postType === 'general' ? defaultCategory || 'Wisdom of The Now' : postType) || 'Wisdom of The Now'
    );
    const [questionContext, setQuestionContext] = useState<'personal_experience' | 'about_someone_else'>('personal_experience');
    const [scripture, setScripture] = useState('');

    // Media State
    const [mediaUrl, setMediaUrl] = useState('');
    const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);

    // Audio State
    const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
    const [audioDuration, setAudioDuration] = useState(0);
    const [previewUrl, setPreviewUrl] = useState<string>('');
    const [audioTitle, setAudioTitle] = useState('');
    const [audioScripture, setAudioScripture] = useState('');

    // Determines whether the Admin prefers uploading files or recording audio
    const [uploadMode, setUploadMode] = useState<'files' | 'audio'>('files');

    const voiceNotesInPostsEnabled = useQuery(api.settings.getVoiceNotesInPostsEnabled);

    const [isLoading, setIsLoading] = useState(false);
    const [isUploadingMedia, setIsUploadingMedia] = useState(false);
    const [error, setError] = useState('');

    const uploadAudioAction = useAction(api.audio.uploadAudio);

    const handleMediaUpload = (url: string, type: 'image' | 'video') => {
        setMediaUrl(url);
        setMediaType(type);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!user) {
            setError('You must be logged in to post');
            return;
        }

        if (content.trim().length < 10) {
            setError('Post must be at least 10 characters');
            return;
        }

        const isAdminAudio = uploadMode === 'audio' && audioBlob && (activeType === 'Ancient Culture' || activeType === 'Wisdom of The Now') && (user.role === 'admin' || user.role === 'super_admin');
        if (isAdminAudio && !audioTitle.trim()) {
            setError('Please provide a title for your audio message.');
            return;
        }

        setError('');
        setIsLoading(true);

        try {
            let finalAudioUrl = undefined;
            let finalAudioDuration = undefined;

            // Handle Cloudinary Audio Upload
            if (audioBlob && uploadMode === 'audio') {
                // Convert Blob to Base64 String
                const reader = new FileReader();
                reader.readAsDataURL(audioBlob);
                const fileBase64 = await new Promise<string>((resolve, reject) => {
                    reader.onloadend = () => {
                        const base64data = reader.result as string;
                        resolve(base64data);
                    };
                    reader.onerror = reject;
                });

                // Call Convex Action to securely push to Cloudinary
                const isAdmin = user.role === 'admin' || user.role === 'super_admin';
                const audioResult = await uploadAudioAction({ fileBase64, isAdmin });
                if (!audioResult.success || !audioResult.audioUrl) {
                    throw new Error("Audio upload explicitly failed remotely.");
                }

                finalAudioUrl = audioResult.audioUrl;
                finalAudioDuration = audioResult.audioDuration;
            }

            const result = await createPost({
                authorId: user._id,
                content: content.trim(),
                category: activeType === 'Ancient Culture' ? 'Ancient Culture' : 'Wisdom of The Now', // Normalize custom types into standard feed categories 
                imageUrl: mediaType === 'image' ? mediaUrl : undefined, // Works across both file and audio modes now 
                videoUrl: mediaType === 'video' && uploadMode === 'files' ? mediaUrl : undefined, // Only files mode allows video attachment
                audioUrl: finalAudioUrl,
                audioDuration: finalAudioDuration,
                audioTitle: audioBlob && uploadMode === 'audio' ? audioTitle : undefined,
                audioScripture: audioBlob && uploadMode === 'audio' ? audioScripture : undefined,
                postType: (activeType === 'question' || activeType === 'prayer') ? activeType : (audioBlob && uploadMode === 'audio') ? 'audio' : 'general',
                questionContext: activeType === 'question' ? questionContext : undefined,
                scripture: activeType === 'prayer' ? scripture : undefined,
            });

            setContent('');
            setMediaUrl('');
            setMediaType(null);
            setAudioBlob(null);
            setAudioDuration(0);
            setPreviewUrl('');
            setAudioTitle('');
            setAudioScripture('');
            setActiveType(defaultCategory || 'Wisdom of The Now');
            onSuccess?.(result.postId);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Failed to create post');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <motion.form
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            onSubmit={handleSubmit}
            className={variant === 'bottom-sheet' ? '' : 'glass rounded-xl p-4 md:p-6 shadow-lg'}
        >
            {isLoading && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-white/80 dark:bg-dark-bg/80 backdrop-blur-sm rounded-xl p-6 text-center"
                >
                    <div className="w-16 h-16 mb-4 relative">
                        <div className="absolute inset-0 border-4 border-primary-500/20 rounded-full" />
                        <div className="absolute inset-0 border-4 border-primary-500 border-t-transparent rounded-full animate-spin" />
                    </div>
                    <h3 className="text-xl font-bold text-primary-600 dark:text-primary-400 mb-2">Sharing Your Thoughts...</h3>
                    <p className="text-sm text-light-muted dark:text-dark-muted max-w-[240px]">
                        Please be patient while we publish your content to the community feed.
                    </p>
                </motion.div>
            )}

            <div className="flex items-center gap-2 mb-4">
                <Sparkles className="w-5 h-5 text-primary-500" />
                <h3 className="text-xl font-semibold text-light-text dark:text-dark-text">
                    {activeType === 'question' ? 'Ask a Question' :
                        activeType === 'prayer' ? 'Share a Prayer Point' :
                            'Share Your Thoughts'}
                </h3>
            </div>

            {error && (
                <div className="mb-4 p-3 rounded-lg bg-red-50 dark:bg-red-950 border border-red-200 dark:border-red-800">
                    <p className="text-sm text-red-700 dark:text-red-300">{error}</p>
                </div>
            )}

            <div className="space-y-4">
                {/* Category Selection - Different for questions vs teachings */}
                <div>
                    <label className="block text-sm font-medium mb-3 text-light-text dark:text-dark-text">
                        Select Category
                    </label>
                    <div className="grid grid-cols-2 sm:flex sm:flex-wrap gap-2 mb-6">
                        {[
                            { id: 'Wisdom of The Now', label: 'Wisdom', color: 'secondary' },
                            { id: 'Ancient Culture', label: 'Ancient', color: 'primary' },
                            { id: 'question', label: 'Question', color: 'blue' },
                            { id: 'prayer', label: 'Prayer', color: 'purple' }
                        ].map((choice) => (
                            <button
                                key={choice.id}
                                type="button"
                                onClick={() => setActiveType(choice.id as any)}
                                className={`flex-1 min-w-[100px] px-3 py-2.5 rounded-xl text-xs font-bold transition-all border ${activeType === choice.id
                                    ? `bg-${choice.color}-500 text-white border-transparent shadow-lg shadow-${choice.color}-500/20 scale-[1.02]`
                                    : 'bg-light-bg dark:bg-dark-bg text-light-muted dark:text-dark-muted border-light-border dark:border-dark-border hover:border-primary-500/30'
                                    }`}
                            >
                                {choice.label}
                            </button>
                        ))}
                    </div>

                    {activeType === 'question' && (
                        <div className="mb-4 animate-in fade-in slide-in-from-top-2">
                            <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text opacity-70">
                                Question Context
                            </label>
                            <div className="grid grid-cols-2 gap-3">
                                <label className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${questionContext === 'personal_experience'
                                    ? 'bg-blue-500/10 border-blue-500/50'
                                    : 'bg-light-card dark:bg-dark-card border-light-border dark:border-dark-border hover:border-blue-500/30'
                                    }`}>
                                    <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${questionContext === 'personal_experience' ? 'border-blue-500' : 'border-gray-400'}`}>
                                        {questionContext === 'personal_experience' && <div className="w-2 h-2 rounded-full bg-blue-500" />}
                                    </div>
                                    <input
                                        type="radio"
                                        name="questionContext"
                                        value="personal_experience"
                                        checked={questionContext === 'personal_experience'}
                                        onChange={() => setQuestionContext('personal_experience')}
                                        className="hidden"
                                    />
                                    <span className={`text-sm font-medium ${questionContext === 'personal_experience' ? 'text-blue-600 dark:text-blue-400' : 'text-light-text dark:text-dark-text'}`}>
                                        Personal
                                    </span>
                                </label>

                                <label className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${questionContext === 'about_someone_else'
                                    ? 'bg-purple-500/10 border-purple-500/50'
                                    : 'bg-light-card dark:bg-dark-card border-light-border dark:border-dark-border hover:border-purple-500/30'
                                    }`}>
                                    <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${questionContext === 'about_someone_else' ? 'border-purple-500' : 'border-gray-400'}`}>
                                        {questionContext === 'about_someone_else' && <div className="w-2 h-2 rounded-full bg-purple-500" />}
                                    </div>
                                    <input
                                        type="radio"
                                        name="questionContext"
                                        value="about_someone_else"
                                        checked={questionContext === 'about_someone_else'}
                                        onChange={() => setQuestionContext('about_someone_else')}
                                        className="hidden"
                                    />
                                    <span className={`text-sm font-medium ${questionContext === 'about_someone_else' ? 'text-purple-600 dark:text-purple-400' : 'text-light-text dark:text-dark-text'}`}>
                                        Someone Else
                                    </span>
                                </label>
                            </div>
                        </div>
                    )}
                </div>

                {/* Scripture Input (Prayer Only) */}
                {activeType === 'prayer' && (
                    <div className="mb-4 animate-in fade-in slide-in-from-top-2">
                        <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text">
                            Scripture Reference <span className="text-xs text-light-muted dark:text-dark-muted font-normal ml-1">(Optional)</span>
                        </label>
                        <input
                            type="text"
                            value={scripture}
                            onChange={(e) => setScripture(e.target.value)}
                            placeholder="e.g. Philippians 4:6-7"
                            className="w-full px-4 py-3 rounded-xl border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg text-light-text dark:text-dark-text placeholder:text-light-muted dark:placeholder:text-dark-muted focus:outline-none focus:ring-2 focus:ring-purple-500/50 focus:border-purple-500 transition-all font-medium"
                        />
                    </div>
                )}

                {/* Audio Details Input (Audio Mode Only) */}
                {uploadMode === 'audio' && (activeType === 'Ancient Culture' || activeType === 'Wisdom of The Now') && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2">
                        <div>
                            <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text">
                                Audio Title <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="text"
                                value={audioTitle}
                                onChange={(e) => setAudioTitle(e.target.value)}
                                placeholder="e.g. The Power of Faith"
                                className="w-full px-4 py-3 rounded-xl border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg text-light-text dark:text-dark-text placeholder:text-light-muted dark:placeholder:text-dark-muted focus:outline-none focus:ring-2 focus:ring-green-500/50 focus:border-green-500 transition-all font-medium"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text">
                                Scripture Passages <span className="text-xs text-light-muted dark:text-dark-muted font-normal ml-1">(Optional)</span>
                            </label>
                            <input
                                type="text"
                                value={audioScripture}
                                onChange={(e) => setAudioScripture(e.target.value)}
                                placeholder="e.g. Hebrews 11:1"
                                className="w-full px-4 py-3 rounded-xl border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg text-light-text dark:text-dark-text placeholder:text-light-muted dark:placeholder:text-dark-muted focus:outline-none focus:ring-2 focus:ring-green-500/50 focus:border-green-500 transition-all font-medium"
                            />
                        </div>
                    </div>
                )}

                {/* Content Input */}
                <div>
                    <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text">
                        {activeType === 'question' ? 'Your Question' :
                            activeType === 'prayer' ? 'Your Prayer Point' :
                                'What did you learn?'}
                    </label>
                    <textarea
                        value={content}
                        onChange={(e) => setContent(e.target.value)}
                        placeholder={activeType === 'question' ? "Type your question here..." :
                            activeType === 'prayer' ? "Share your prayer request..." :
                                "Share your insights, revelations, and key takeaways from today's teaching session..."}
                        rows={6}
                        className="w-full px-4 py-3 rounded-lg border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg text-light-text dark:text-dark-text placeholder:text-light-muted dark:placeholder:text-dark-muted focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent resize-none"
                        required
                    />
                    <p className="mt-1 text-xs text-light-muted dark:text-dark-muted">
                        {content.length} characters
                    </p>
                </div>

                {/* Media OR Audio Upload Configuration (Admins only get audio rights for Wisdom/Ancient) */}
                {(activeType === 'Ancient Culture' || activeType === 'Wisdom of The Now') && (user?.role === 'admin' || user?.role === 'super_admin') ? (
                    <div>
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-2">
                            <label className="block text-sm font-medium text-light-text dark:text-dark-text">
                                Add Media / Audio
                            </label>

                            <div className="flex flex-wrap items-center bg-gray-100 dark:bg-gray-800 p-1 rounded-lg w-fit">
                                <button
                                    type="button"
                                    onClick={() => setUploadMode('files')}
                                    className={`px-3 py-1 text-xs font-semibold rounded-md transition-all ${uploadMode === 'files'
                                        ? 'bg-white dark:bg-gray-600 shadow-sm text-gray-900 dark:text-white'
                                        : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                                        }`}
                                >
                                    Upload File
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setUploadMode('audio')}
                                    className={`px-3 py-1 text-xs font-semibold rounded-md transition-all ${uploadMode === 'audio'
                                        ? 'bg-white dark:bg-gray-600 shadow-sm text-gray-900 dark:text-white'
                                        : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                                        }`}
                                >
                                    Record Audio
                                </button>
                            </div>
                        </div>

                        {uploadMode === 'audio' ? (
                            <div className="mt-4">
                                {audioBlob ? (
                                    <div className="flex items-center justify-between p-4 bg-green-50 dark:bg-green-900/20 rounded-xl border border-green-200 dark:border-green-800">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-800 flex items-center justify-center">
                                                <Sparkles className="w-5 h-5 text-green-600 dark:text-green-400" />
                                            </div>
                                            <div>
                                                <p className="font-semibold text-green-800 dark:text-green-300">Audio Ready to Post</p>
                                                <p className="text-xs text-green-600 dark:text-green-400">Length: {audioDuration} seconds</p>
                                            </div>
                                        </div>

                                        <div className="flex flex-col items-end gap-2">
                                            {previewUrl && (
                                                <audio
                                                    controls
                                                    controlsList="nodownload noplaybackrate"
                                                    src={previewUrl}
                                                    className="h-8 w-40 max-w-full"
                                                />
                                            )}
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    setAudioBlob(null);
                                                    setAudioDuration(0);
                                                    setPreviewUrl('');
                                                }}
                                                className="text-xs font-bold text-red-500 hover:text-red-600 px-3 py-1 bg-red-50 dark:bg-red-900/10 rounded-full"
                                            >
                                                Remove
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <AudioRecorder
                                        onRecordingComplete={(blob, duration) => {
                                            setAudioBlob(blob);
                                            setAudioDuration(duration);
                                            setPreviewUrl(URL.createObjectURL(blob));
                                        }}
                                        onCancel={() => setUploadMode('files')}
                                    />
                                )}

                                {/* Cover Art Upload Section explicitly included within Audio Upload Mode */}
                                <div className="mt-6 border-t border-light-border dark:border-dark-border pt-4">
                                    <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text">
                                        Cover Art Thumbnail <span className="text-xs text-light-muted font-normal ml-1">(Optional)</span>
                                    </label>
                                    <MediaUpload
                                        onUploadComplete={handleMediaUpload}
                                        onUploadChange={setIsUploadingMedia}
                                        allowVideo={false}
                                        currentMedia={mediaUrl ? { url: mediaUrl, type: mediaType! } : undefined}
                                    />
                                    <p className="mt-1 text-xs text-accent-500 pt-1">
                                        ⚡ Attach an image to use as the visual thumbnail for this audio post.
                                    </p>
                                </div>
                            </div>
                        ) : (
                            <div>
                                <MediaUpload
                                    onUploadComplete={handleMediaUpload}
                                    onUploadChange={setIsUploadingMedia}
                                    allowVideo={true}
                                    currentMedia={mediaUrl ? { url: mediaUrl, type: mediaType! } : undefined}
                                />
                                <p className="mt-1 text-xs text-accent-500 pt-1">
                                    ⚡ As an admin, you can upload both images and videos
                                </p>
                            </div>
                        )}
                    </div>
                ) : (
                    <div>
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-2">
                            <label className="block text-sm font-medium text-light-text dark:text-dark-text">
                                Add Media / Voice Note <span className="text-xs text-light-muted font-normal ml-1">(Optional)</span>
                            </label>

                            <div className="flex flex-wrap items-center bg-gray-100 dark:bg-gray-800 p-1 rounded-lg w-fit">
                                <button
                                    type="button"
                                    onClick={() => setUploadMode('files')}
                                    className={`px-3 py-1 text-xs font-semibold rounded-md transition-all ${uploadMode === 'files'
                                        ? 'bg-white dark:bg-gray-600 shadow-sm text-gray-900 dark:text-white'
                                        : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                                        }`}
                                >
                                    Upload Image
                                </button>
                                {voiceNotesInPostsEnabled !== false && (
                                    <button
                                        type="button"
                                        onClick={() => setUploadMode('audio')}
                                        className={`px-3 py-1 text-xs font-semibold rounded-md transition-all ${uploadMode === 'audio'
                                            ? 'bg-white dark:bg-gray-600 shadow-sm text-gray-900 dark:text-white'
                                            : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
                                            }`}
                                    >
                                        Voice Note
                                    </button>
                                )}
                            </div>
                        </div>

                        {uploadMode === 'audio' ? (
                            <div className="mt-4">
                                {audioBlob ? (
                                    <div className="flex items-center justify-between p-4 bg-green-50 dark:bg-green-900/20 rounded-xl border border-green-200 dark:border-green-800">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-800 flex items-center justify-center">
                                                <Sparkles className="w-5 h-5 text-green-600 dark:text-green-400" />
                                            </div>
                                            <div>
                                                <p className="font-semibold text-green-800 dark:text-green-300">Audio Ready to Post</p>
                                                <p className="text-xs text-green-600 dark:text-green-400">Length: {audioDuration} seconds</p>
                                            </div>
                                        </div>

                                        <div className="flex flex-col items-end gap-2">
                                            {previewUrl && (
                                                <audio
                                                    controls
                                                    controlsList="nodownload noplaybackrate"
                                                    src={previewUrl}
                                                    className="h-8 w-40 max-w-full"
                                                />
                                            )}
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    setAudioBlob(null);
                                                    setAudioDuration(0);
                                                    setPreviewUrl('');
                                                }}
                                                className="text-xs font-bold text-red-500 hover:text-red-600 px-3 py-1 bg-red-50 dark:bg-red-900/10 rounded-full"
                                            >
                                                Remove
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <AudioRecorder
                                        onRecordingComplete={(blob, duration) => {
                                            setAudioBlob(blob);
                                            setAudioDuration(duration);
                                            setPreviewUrl(URL.createObjectURL(blob));
                                        }}
                                        onCancel={() => setUploadMode('files')}
                                    />
                                )}
                            </div>
                        ) : (
                            <div>
                                <MediaUpload
                                    onUploadComplete={handleMediaUpload}
                                    onUploadChange={setIsUploadingMedia}
                                    allowVideo={false}
                                    currentMedia={mediaUrl ? { url: mediaUrl, type: mediaType! } : undefined}
                                />
                            </div>
                        )}
                    </div>
                )}

                <div className="flex items-center justify-between">
                    <p className="text-xs text-light-muted dark:text-dark-muted">
                        📝 Be among the first 5 to post and earn the <strong className="text-primary-500">SENT</strong> badge!
                    </p>
                    <Button
                        type="submit"
                        variant="primary"
                        isLoading={isLoading}
                        disabled={content.trim().length < 10 || isUploadingMedia}
                    >
                        {isUploadingMedia ? 'Uploading Media...' : 'Post'}
                    </Button>
                </div>
            </div>
        </motion.form>
    );
}
