import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams, Link } from 'react-router-dom';
import { useMutation } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Lock, CheckCircle2, AlertCircle } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export function ResetPassword() {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const token = searchParams.get('token');

    const resetPassword = useMutation(api.passwordReset.resetPassword);

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (!token) {
            setError("Missing reset token. Please use the link from your email.");
        }
    }, [token]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        if (!token) return;

        if (password.length < 6) {
            setError("Password must be at least 6 characters");
            return;
        }

        if (password !== confirmPassword) {
            setError("Passwords do not match");
            return;
        }

        setIsLoading(true);

        try {
            await resetPassword({
                token,
                newPassword: password,
            });
            setIsSuccess(true);
            setTimeout(() => {
                navigate('/login');
            }, 3000);
        } catch (err: any) {
            setError(err.message || "Failed to reset password");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="w-full max-w-md mx-auto"
            >
                <Card glass>
                    <CardHeader className="pt-8 pt-6">
                        <CardTitle className="text-2xl font-bold">Reset Password</CardTitle>
                        <p className="text-light-muted dark:text-dark-muted mt-2">
                            Enter your new password below.
                        </p>
                    </CardHeader>
                    <CardContent className="pb-8">
                        <AnimatePresence mode="wait">
                            {!isSuccess ? (
                                <motion.form
                                    key="form"
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    exit={{ opacity: 0 }}
                                    onSubmit={handleSubmit}
                                    className="space-y-4"
                                >
                                    {error && (
                                        <div className="p-3 rounded-xl bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800 text-sm text-red-600 dark:text-red-400 flex items-start gap-3">
                                            <AlertCircle className="w-5 h-5 flex-shrink-0" />
                                            {error}
                                        </div>
                                    )}

                                    <Input
                                        label="New Password"
                                        type="password"
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        icon={<Lock className="w-5 h-5" />}
                                        placeholder="••••••••"
                                        required
                                        autoFocus
                                        disabled={!token}
                                    />

                                    <Input
                                        label="Confirm New Password"
                                        type="password"
                                        value={confirmPassword}
                                        onChange={(e) => setConfirmPassword(e.target.value)}
                                        icon={<Lock className="w-5 h-5" />}
                                        placeholder="••••••••"
                                        required
                                        disabled={!token}
                                    />

                                    <Button
                                        type="submit"
                                        variant="primary"
                                        className="w-full h-12 mt-2"
                                        isLoading={isLoading}
                                        disabled={!token}
                                    >
                                        Update Password
                                    </Button>

                                    {!token && (
                                        <Link to="/forgot-password" className="block text-center text-primary-500 hover:underline">
                                            Request a new link
                                        </Link>
                                    )}
                                </motion.form>
                            ) : (
                                <motion.div
                                    key="success"
                                    initial={{ opacity: 0, scale: 0.95 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    className="text-center py-4"
                                >
                                    <div className="w-16 h-16 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
                                        <CheckCircle2 className="w-8 h-8 text-green-600 dark:text-green-400" />
                                    </div>
                                    <h3 className="text-xl font-bold mb-2">Password Updated!</h3>
                                    <p className="text-light-muted dark:text-dark-muted mb-6">
                                        Your password has been successfully reset. Redirecting you to login...
                                    </p>
                                    <Button
                                        variant="primary"
                                        className="w-full"
                                        onClick={() => navigate('/login')}
                                    >
                                        Go to Login Now
                                    </Button>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </CardContent>
                </Card>
            </motion.div>
        </div>
    );
}
