import { useState } from 'react';
import { motion } from 'framer-motion';
import { AdminContacts } from '../AdminContacts';
import { ChatPage } from '../ChatPage';
import { Mail, MessageCircle, Mic } from 'lucide-react';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useAuth } from '@/hooks/useAuth';

export function AdminChat() {
    const { user } = useAuth();
    const [activeTab, setActiveTab] = useState<'contacts' | 'live-chat'>('contacts');

    const voiceEnabled = useQuery(api.settings.getChatVoiceNotesEnabledForMembers);
    const toggleVoice = useMutation(api.settings.toggleChatVoiceNotesEnabledForMembers);

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="h-[calc(100vh-theme(spacing.24))] flex flex-col overflow-hidden"
        >
            {/* Header / Tabs */}
            <div className="flex-shrink-0 mb-4 px-1">
                <div className="flex items-center justify-between mb-4">
                    <div>
                        <h1 className="text-3xl md:text-4xl font-bold text-primary-600 dark:text-primary-400">
                            Communications
                        </h1>
                        <p className="text-light-muted dark:text-dark-muted">
                            Manage contact requests and live chat interactions
                        </p>
                    </div>

                    {/* Voice Note Toggle */}
                    {voiceEnabled !== undefined && user && (
                        <div className="flex items-center gap-3 bg-gray-50 dark:bg-gray-800/60 border border-light-border dark:border-dark-border rounded-xl px-4 py-2.5">
                            <Mic className={`w-4 h-4 ${voiceEnabled ? 'text-primary-500' : 'text-gray-400'}`} />
                            <div className="flex flex-col">
                                <span className="text-xs font-bold text-light-text dark:text-dark-text">Member Voice Notes</span>
                                <span className="text-[10px] text-light-muted">{voiceEnabled ? 'Enabled' : 'Disabled'} for members</span>
                            </div>
                            <button
                                onClick={() => toggleVoice({ adminId: user._id, enabled: !voiceEnabled })}
                                className={`relative w-10 h-5 rounded-full transition-colors ml-2 ${voiceEnabled ? 'bg-primary-500' : 'bg-gray-300 dark:bg-gray-600'
                                    }`}
                            >
                                <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform ${voiceEnabled ? 'translate-x-5' : 'translate-x-0.5'
                                    }`} />
                            </button>
                        </div>
                    )}
                </div>

                <div className="flex gap-2 p-1 bg-light-card dark:bg-dark-card rounded-xl border border-light-border dark:border-dark-border w-fit">
                    <button
                        onClick={() => setActiveTab('contacts')}
                        className={`
                            flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all
                            ${activeTab === 'contacts'
                                ? 'bg-primary-500 text-white shadow-md'
                                : 'text-light-muted dark:text-dark-muted hover:bg-gray-100 dark:hover:bg-gray-800'
                            }
                        `}
                    >
                        <Mail className="w-4 h-4" />
                        Contact Requests
                    </button>
                    <button
                        onClick={() => setActiveTab('live-chat')}
                        className={`
                             flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all
                            ${activeTab === 'live-chat'
                                ? 'bg-primary-500 text-white shadow-md'
                                : 'text-light-muted dark:text-dark-muted hover:bg-gray-100 dark:hover:bg-gray-800'
                            }
                        `}
                    >
                        <MessageCircle className="w-4 h-4" />
                        Live Chat
                    </button>
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-hidden relative rounded-2xl border border-light-border dark:border-dark-border bg-white dark:bg-dark-card shadow-sm">
                <div className="absolute inset-0 overflow-hidden">
                    {activeTab === 'contacts' ? (
                        <div className="h-full overflow-y-auto p-6 custom-thin-scrollbar">
                            <AdminContacts />
                        </div>
                    ) : (
                        <div className="h-full w-full">
                            <ChatPage isEmbedded={true} />
                        </div>
                    )}
                </div>
            </div>
        </motion.div>
    );
}
