import { useState, useEffect, useRef } from 'react';
import { useQuery, usePaginatedQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useAuth } from '@/hooks/useAuth';
import { useLocation } from 'react-router-dom';
import { PostCard } from './PostCard';
import { PostCardSkeleton } from '@/components/ui/Skeletons';
import { AnimatePresence, motion } from 'framer-motion';
import { ArrowUp, CheckCircle, Loader2, RefreshCw } from 'lucide-react';
import { Id } from '../../../convex/_generated/dataModel';

interface PostFeedProps {
    category?: 'Ancient Culture' | 'Wisdom of The Now';
    onCommentClick?: (post: any) => void;
    selectedPostId?: string;
    onlyOfficial?: boolean;
}

export function PostFeed(props: PostFeedProps) {
    const { category, onCommentClick, onlyOfficial } = props;
    const { user: _user } = useAuth();
    const location = useLocation();

    // ─── Pinned "just posted" post (shown to the creator immediately) ─────────
    const newPostId = (location.state as any)?.newPostId as string | undefined;
    const [pinnedPostId, setPinnedPostId] = useState<string | undefined>(newPostId);

    useEffect(() => {
        if (newPostId) {
            setPinnedPostId(newPostId);
            window.history.replaceState({ ...window.history.state, usr: {} }, '');
        }
    }, [newPostId]);

    const pinnedPost = useQuery(
        api.posts.getPost,
        pinnedPostId ? { postId: pinnedPostId as Id<'posts'> } : 'skip'
    );

    // ─── Filter State ─────────────────────────────────────────────────────────
    const [filter, setFilter] = useState<{ type: 'postType' | 'all'; value?: string }>({
        type: 'all'
    });

    // ─── FIXED cutoffTime — never changes ─────────────────────────────────────
    // This is the moment the user opened the feed.
    //   • Posts BEFORE this → shown in the paginated feed (stable, no jumps)
    //   • Posts AFTER this  → counted and fetched by getNewPosts (live, reactive)
    //
    // The paginated query args NEVER change, so usePaginatedQuery never restarts.
    const [cutoffTime] = useState(() => Date.now());

    // ─── Paginated Feed (stable — args never change) ───────────────────────────
    const { results, status, loadMore } = usePaginatedQuery(
        api.posts.getPaginatedFeed,
        {
            postType: filter.type === 'postType' ? filter.value as any : undefined,
            category,
            onlyOfficial,
            cutoffTime,
            userId: _user?._id,
        },
        { initialNumItems: 10 }
    );

    // ─── Live "New Posts" background fetch ────────────────────────────────────
    // Convex keeps this reactive — the instant someone creates a post, this query
    // automatically updates with the full post data (author, hasLiked, etc).
    // The data is already cached in memory when the user clicks the button,
    // so revealing it is INSTANT — no network request needed at click time.
    const newPosts = useQuery(api.posts.getNewPosts, {
        cutoffTime,
        postType: filter.type === 'postType' ? filter.value : undefined,
        category,
        excludeUserId: _user?._id,
        userId: _user?._id,
    }) ?? [];

    // ─── Notification Badge State ──────────────────────────────────────────────
    // We track how many new posts the user has already "acknowledged" (clicked).
    // unseenCount = new posts arrived since last click (or since page load).
    const [seenCount, setSeenCount] = useState(0);
    const unseenCount = Math.max(0, newPosts.length - seenCount);

    // ─── Posts revealed by clicking the "New Posts" button ────────────────────
    // A snapshot of newPosts at the moment the user clicks. Displayed at the
    // very top of the feed, above the paginated results.
    const [displayedNewPosts, setDisplayedNewPosts] = useState<any[]>([]);

    // ─── "New Posts" button click — INSTANT reveal, zero loading ──────────────
    // The posts are already fetched and cached by Convex. We just move them
    // from the background query into the visible list. No spinner, no delay.
    const handleNewPostsRefresh = () => {
        const snapshot = [...newPosts];   // snapshot in case query updates mid-render
        setDisplayedNewPosts(snapshot);
        setSeenCount(newPosts.length);    // mark all as seen so button disappears
        setPinnedPostId(undefined);       // clear the creator's pinned post if present

        // Use requestAnimationFrame so React paints the new posts BEFORE scrolling
        requestAnimationFrame(() => {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    };

    // ─── Infinite Scroll ──────────────────────────────────────────────────────
    const loadMoreRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting && status === 'CanLoadMore') {
                    loadMore(10);
                }
            },
            { threshold: 0.1 }
        );
        if (loadMoreRef.current) observer.observe(loadMoreRef.current);
        return () => observer.disconnect();
    }, [status, loadMore]);

    // ─── Scroll To Top button ─────────────────────────────────────────────────
    const [showScrollTop, setShowScrollTop] = useState(false);
    useEffect(() => {
        const handleScroll = () => setShowScrollTop(window.scrollY > 2000);
        window.addEventListener('scroll', handleScroll, { passive: true });
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // ─── Initial Loading skeleton ─────────────────────────────────────────────
    if (status === 'LoadingFirstPage' || results === undefined) {
        return (
            <div className="space-y-4">
                <PostCardSkeleton />
                <PostCardSkeleton />
                <PostCardSkeleton />
            </div>
        );
    }

    // Build a set of IDs that are already shown at the top so we never duplicate
    const topIds = new Set<string>([
        ...(pinnedPostId ? [pinnedPostId] : []),
        ...displayedNewPosts.map((p: any) => p._id),
    ]);
    const paginatedResults = results.filter((p: any) => !topIds.has(p._id));

    return (
        <div className="space-y-6 relative min-h-[50vh]">

            {/* ── Sticky "New Posts" notification button ── */}
            <AnimatePresence>
                {unseenCount > 0 && (
                    <motion.div
                        initial={{ opacity: 0, y: -24, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: -24, scale: 0.95 }}
                        transition={{ type: 'spring', stiffness: 400, damping: 30 }}
                        className="flex justify-center mb-2 sticky top-20 z-30 pointer-events-none"
                    >
                        <button
                            onClick={handleNewPostsRefresh}
                            className="pointer-events-auto flex items-center gap-2 px-5 py-2.5 rounded-full shadow-2xl bg-gray-900 dark:bg-gray-800 hover:bg-gray-800 dark:hover:bg-gray-700 text-white text-sm font-semibold border border-primary-500/40 backdrop-blur-md transition-transform hover:scale-105 active:scale-95"
                        >
                            <motion.span
                                animate={{ rotate: [0, -15, 15, -10, 10, 0] }}
                                transition={{ duration: 0.6, delay: 0.2 }}
                            >
                                <RefreshCw className="w-4 h-4 text-primary-400" />
                            </motion.span>
                            {unseenCount} New {unseenCount === 1 ? 'Post' : 'Posts'}
                            <span className="text-primary-300">— Tap to see</span>
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* ── Filters ── */}
            {!category && (
                <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
                    {[
                        { label: 'All Posts', value: null, activeClass: 'bg-primary-500 border-primary-500 text-white shadow-primary-500/20' },
                        { label: 'Prayers', value: 'prayer', activeClass: 'bg-purple-500 border-purple-500 text-white shadow-purple-500/20' },
                        { label: 'Questions', value: 'question', activeClass: 'bg-blue-500 border-blue-500 text-white shadow-blue-500/20' },
                    ].map(({ label, value, activeClass }) => {
                        const isActive = value === null ? filter.type === 'all' : (filter.type === 'postType' && filter.value === value);
                        return (
                            <button
                                key={label}
                                onClick={() => value === null
                                    ? setFilter({ type: 'all' })
                                    : setFilter({ type: 'postType', value })}
                                className={`whitespace-nowrap px-4 py-2 sm:px-6 sm:py-2.5 rounded-full font-bold transition-all text-xs sm:text-sm border shadow-sm active:scale-95 ${isActive
                                    ? activeClass
                                    : 'bg-white dark:bg-dark-card text-gray-600 dark:text-gray-300 border-gray-200 dark:border-gray-800 hover:bg-gray-50 dark:hover:bg-white/5'
                                    }`}
                            >
                                {label}
                            </button>
                        );
                    })}
                </div>
            )}

            {/* ── Creator's pinned "Just posted" card ── */}
            <AnimatePresence>
                {pinnedPost && (
                    <motion.div
                        initial={{ opacity: 0, y: -16, scale: 0.98 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.98 }}
                        transition={{ duration: 0.3, ease: 'easeOut' }}
                    >
                        <div className="flex items-center gap-2 mb-2 px-1">
                            <CheckCircle className="w-4 h-4 text-green-500" />
                            <span className="text-xs font-semibold text-green-600 dark:text-green-400">
                                Your post is live!
                            </span>
                        </div>
                        <div className="ring-2 ring-green-500/30 rounded-2xl">
                            <PostCard
                                post={pinnedPost as any}
                                onCommentClick={() => onCommentClick?.(pinnedPost)}
                                hasUserLiked={(pinnedPost as any).hasLiked ?? false}
                            />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* ── Revealed new posts (from "New Posts" button click) ── */}
            <AnimatePresence>
                {displayedNewPosts.length > 0 && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className="space-y-4"
                    >
                        {displayedNewPosts.map((post: any, i: number) => (
                            <motion.div
                                key={post._id}
                                initial={{ opacity: 0, y: -12 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: i * 0.05, duration: 0.25 }}
                            >
                                <PostCard
                                    post={post}
                                    onCommentClick={() => onCommentClick?.(post)}
                                    hasUserLiked={post.hasLiked ?? false}
                                />
                            </motion.div>
                        ))}
                    </motion.div>
                )}
            </AnimatePresence>

            {/* ── Paginated (stable) posts ── */}
            {paginatedResults.length === 0 && !pinnedPost && displayedNewPosts.length === 0 ? (
                <div className="text-center py-12 glass rounded-xl">
                    <p className="text-light-muted dark:text-dark-muted">No posts yet.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {paginatedResults.map((post: any) => (
                        <PostCard
                            key={post._id}
                            post={post as any}
                            onCommentClick={() => onCommentClick?.(post)}
                            hasUserLiked={(post as any).hasLiked}
                        />
                    ))}
                </div>
            )}

            {/* ── Infinite Scroll trigger ── */}
            <div ref={loadMoreRef} className="h-16 flex items-center justify-center">
                {status === 'LoadingMore' && (
                    <div className="flex items-center gap-2 text-light-muted dark:text-dark-muted">
                        <Loader2 className="w-5 h-5 animate-spin text-primary-500" />
                        <span className="text-sm font-medium">Loading more...</span>
                    </div>
                )}
            </div>

            {/* ── Scroll To Top ── */}
            <AnimatePresence>
                {showScrollTop && (
                    <motion.button
                        initial={{ opacity: 0, scale: 0.5 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.5 }}
                        onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                        className="fixed bottom-20 right-4 md:bottom-10 md:right-10 p-3 md:p-4 rounded-full bg-gray-900 text-white shadow-2xl z-40 hover:bg-gray-800 active:scale-90 transition-all group border border-primary-500/30"
                    >
                        <ArrowUp className="w-5 h-5 md:w-6 md:h-6 group-hover:-translate-y-1 transition-transform" />
                    </motion.button>
                )}
            </AnimatePresence>
        </div>
    );
}
