import { useState } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { useTheme } from '@/context/ThemeContext';
import { 
    LogOut, Sun, Moon, LayoutDashboard, User, 
    Trophy, Bookmark, Brain, Wallet, 
    Settings, ChevronRight, 
    ShieldCheck, Info, FileText, LucideIcon
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { ConfirmationModal } from '@/components/ui/ConfirmationModal';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { BackButton } from '@/components/ui/BackButton';

interface MenuItem {
    icon: LucideIcon;
    label: string;
    path: string;
    color: string;
    field?: string;
    badge?: number;
    hasUpdate?: boolean;
}

interface MenuGroup {
    title: string;
    items: MenuItem[];
}

export function MobileMenu() {
    const { user, logout } = useAuth();
    const { theme, toggleTheme } = useTheme();
    const navigate = useNavigate();
    const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

    const badgeCounts = useQuery(api.stats.getBadgeCounts, user?._id ? { userId: user._id } : 'skip');
    const updateLastViewed = useMutation(api.users.updateLastViewed);

    const handleNavClick = async (path: string, field?: string) => {
        if (field && user) {
            await updateLastViewed({ userId: user._id, field: field as any });
        }
        navigate(path);
    };

    const handleLogout = () => {
        logout();
        navigate('/');
    };

    const menuGroups: MenuGroup[] = [
        {
            title: "Your Growth",
            items: [
                { 
                    icon: Wallet, 
                    label: "Banking", 
                    path: "/banking", 
                    color: "text-emerald-500",
                    field: "lastViewedBanking",
                    hasUpdate: (badgeCounts?.banking || 0) > 0
                },
                { 
                    icon: Trophy, 
                    label: "Leaderboard", 
                    path: "/leaderboard", 
                    color: "text-amber-500",
                    field: "lastViewedLeaderboard",
                    hasUpdate: (badgeCounts?.leaderboard || 0) > 0
                },
                { icon: Bookmark, label: "Saved Posts", path: "/saved-posts", color: "text-purple-500" },
                { icon: Brain, label: "Diamond Challenge", path: "/diamond-challenge", color: "text-cyan-500" },
            ]
        },
        {
            title: "Account",
            items: [
                { icon: User, label: "Your Profile", path: "/profile", color: "text-gray-500" },
                { icon: Settings, label: "Settings", path: "/profile", color: "text-gray-400" },
            ]
        },
        {
            title: "Information",
            items: [
                { icon: Info, label: "About Baptizo", path: "/about", color: "text-primary-400" },
                { icon: ShieldCheck, label: "Privacy Policy", path: "/privacy", color: "text-slate-400" },
                { icon: FileText, label: "Terms of Service", path: "/terms", color: "text-slate-400" },
            ]
        }
    ];

    return (
        <div className="min-h-screen bg-light-bg dark:bg-dark-bg pb-20">
            {/* Header Area */}
            <div className="sticky top-0 z-30 glass border-b border-light-border/50 dark:border-dark-border/50 px-4 py-4 flex items-center justify-between">
                <BackButton />
                {/* <h1 className="text-xl font-bold font-display text-light-text ml-10 dark:text-dark-text">Menu</h1> */}
                <div className="w-10"></div> {/* Spacer for symmetry */}
            </div>

            <div className="container mx-auto px-4 py-6 space-y-8">
                {/* Profile Section */}
                {user && (
                    <motion.div 
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="p-5 rounded-3xl bg-gradient-to-br from-primary-500/10 to-secondary-500/10 border border-primary-500/20 shadow-sm"
                    >
                        <div className="flex items-center gap-4">
                            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold text-2xl overflow-hidden shadow-lg border-2 border-white dark:border-dark-bg">
                                {user.avatarUrl ? (
                                    <img src={user.avatarUrl} alt={user.name} className="w-full h-full object-cover" />
                                ) : (
                                    user.name[0]
                                )}
                            </div>
                            <div className="flex-1 min-w-0">
                                <h2 className="text-xl font-bold text-light-text dark:text-dark-text truncate leading-tight">
                                    {user.name}
                                </h2>
                                <p className="text-sm text-light-muted dark:text-dark-muted truncate">
                                    {user.email}
                                </p>
                                {(user.role as string) !== 'member' && (
                                    <span className="inline-block mt-1 px-2 py-0.5 rounded-full bg-primary-500/20 text-primary-600 dark:text-primary-400 text-[10px] font-bold uppercase tracking-wider">
                                        {user.role.replace('_', ' ')}
                                    </span>
                                )}
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3 mt-5">
                            <Button 
                                variant="outline" 
                                className="rounded-xl h-10 text-xs font-bold"
                                onClick={() => navigate('/profile')}
                            >
                                Edit Profile
                            </Button>
                            <Button 
                                variant="primary" 
                                className="rounded-xl h-10 text-xs font-bold"
                                onClick={() => navigate(`/profile/${user._id}`)}
                            >
                                Public View
                            </Button>
                        </div>
                    </motion.div>
                )}

                {/* Navigation Groups */}
                <div className="space-y-6">
                    {menuGroups.map((group) => (
                        <div key={group.title} className="space-y-2">
                            <h3 className="px-2 text-[11px] font-black uppercase tracking-[0.2em] text-light-muted dark:text-dark-muted opacity-70">
                                {group.title}
                            </h3>
                            <div className="bg-light-card/40 dark:bg-dark-card/40 rounded-3xl border border-light-border/50 dark:border-dark-border/50 overflow-hidden">
                                {group.items.map((item, itemIdx) => (
                                    <button
                                        key={item.label}
                                        onClick={() => handleNavClick(item.path, item.field)}
                                        className={`w-full flex items-center gap-4 p-4 hover:bg-primary-500/5 transition-colors text-left group ${
                                            itemIdx !== group.items.length - 1 ? 'border-b border-light-border/30 dark:border-dark-border/30' : ''
                                        }`}
                                    >
                                        <div className={`p-2 rounded-xl bg-white dark:bg-dark-bg border border-light-border/50 dark:border-dark-border/50 shadow-sm group-active:scale-90 transition-transform ${item.color}`}>
                                            <item.icon className="w-5 h-5" />
                                        </div>
                                        <span className="flex-1 font-bold text-light-text dark:text-dark-text text-sm">
                                            {item.label}
                                        </span>
                                        <div className="flex items-center gap-2">
                                            {item.badge !== undefined && item.badge > 0 && (
                                                <span className="bg-green-500 text-white text-[10px] font-black h-5 min-w-[20px] px-1.5 flex items-center justify-center rounded-full shadow-[0_0_8px_rgba(34,197,94,0.3)]">
                                                    {item.badge > 9 ? '9+' : item.badge}
                                                </span>
                                            )}
                                            {item.hasUpdate && (
                                                <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]" />
                                            )}
                                            <ChevronRight className="w-4 h-4 text-light-muted dark:text-dark-muted opacity-50" />
                                        </div>
                                    </button>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>

                {/* Admin/Board Sections */}
                {(user?.role === 'admin' || user?.role === 'super_admin') && (
                    <div className="space-y-2">
                        <h3 className="px-2 text-[11px] font-black uppercase tracking-[0.2em] text-primary-500 leading-none">
                            Management
                        </h3>
                        <button
                            onClick={() => navigate('/admin')}
                            className="w-full flex items-center gap-4 p-4 bg-primary-500/10 hover:bg-primary-500/20 rounded-3xl border border-primary-500/20 transition-all group"
                        >
                            <div className="p-2 rounded-xl bg-white dark:bg-dark-bg border border-primary-500/50 shadow-sm transition-transform group-active:scale-95">
                                <LayoutDashboard className="w-5 h-5 text-primary-500" />
                            </div>
                            <span className="flex-1 font-black text-primary-600 dark:text-primary-400 text-sm">
                                Admin Dashboard
                            </span>
                            <ChevronRight className="w-4 h-4 text-primary-500 opacity-50" />
                        </button>
                    </div>
                )}

                {user?.role === 'board_member' && (
                    <div className="space-y-2">
                        <h3 className="px-2 text-[11px] font-black uppercase tracking-[0.2em] text-secondary-500 leading-none">
                            Governance
                        </h3>
                        <button
                            onClick={() => navigate('/board')}
                            className="w-full flex items-center gap-4 p-4 bg-secondary-500/10 hover:bg-secondary-500/20 rounded-3xl border border-secondary-500/20 transition-all group"
                        >
                            <div className="p-2 rounded-xl bg-white dark:bg-dark-bg border border-secondary-500/50 shadow-sm transition-transform group-active:scale-95">
                                <LayoutDashboard className="w-5 h-5 text-secondary-500" />
                            </div>
                            <span className="flex-1 font-black text-secondary-600 dark:text-secondary-400 text-sm">
                                Board Member Portal
                            </span>
                            <ChevronRight className="w-4 h-4 text-secondary-500 opacity-50" />
                        </button>
                    </div>
                )}

                {/* Appearance & Settings */}
                <div className="bg-light-card/60 dark:bg-dark-card/60 rounded-3xl border border-light-border dark:border-dark-border p-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-xl bg-white dark:bg-dark-bg border border-light-border/50 dark:border-dark-border/50">
                                {theme === 'dark' ? <Moon className="w-5 h-5 text-indigo-400" /> : <Sun className="w-5 h-5 text-amber-500" />}
                            </div>
                            <div>
                                <h4 className="text-sm font-bold text-light-text dark:text-dark-text leading-none">Appearance</h4>
                                <p className="text-[10px] text-light-muted dark:text-dark-muted mt-1">{theme === 'dark' ? 'Dark Mode' : 'Light Mode'}</p>
                            </div>
                        </div>
                        <button
                            onClick={toggleTheme}
                            className="w-12 h-6 rounded-full bg-light-muted/20 dark:bg-dark-muted/20 relative p-1 transition-colors"
                        >
                            <motion.div 
                                animate={{ x: theme === 'dark' ? 24 : 0 }}
                                className="w-4 h-4 rounded-full bg-primary-500 shadow-sm"
                            />
                        </button>
                    </div>
                </div>

                {/* Logout Button */}
                {user && (
                    <button
                        onClick={() => setShowLogoutConfirm(true)}
                        className="w-full p-5 rounded-3xl bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center gap-3 font-black text-sm active:scale-[0.98]"
                    >
                        <LogOut className="w-5 h-5" />
                        Log Out Account
                    </button>
                )}

                <div className="text-center pt-4">
                    <p className="text-[10px] font-medium text-light-muted dark:text-dark-muted opacity-50 uppercase tracking-widest">
                        Baptizo Community v2.4.0
                    </p>
                </div>
            </div>

            <ConfirmationModal
                isOpen={showLogoutConfirm}
                onClose={() => setShowLogoutConfirm(false)}
                onConfirm={handleLogout}
                title="Confirm Logout"
                description="Are you sure you want to log out of your account?"
                confirmText="Logout"
                cancelText="Cancel"
            />
        </div>
    );
}
