import { useState, useRef, useEffect } from 'react';
import { useQuery, useMutation, useAction } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { useAuth } from '@/hooks/useAuth';
import { Avatar } from '@/components/ui/Avatar';
import {
    ArrowLeft, Search, MessageSquare, MessageCircle, Sparkles,
    Users, Lock, Unlock, Image as ImageIcon, Loader2,
} from 'lucide-react';

import { formatDistanceToNow } from 'date-fns';
import { useNavigate, Link } from 'react-router-dom';
import { ChatListSkeleton, MessagesSkeleton } from '@/components/ui/Skeletons';
import { uploadToImageKit } from '@/lib/imagekit';
import { Id } from '../../convex/_generated/dataModel';

// Chat sub-components
import { AvatarPreviewModal } from '@/components/chat/AvatarPreviewModal';
import { SeenByModal } from '@/components/chat/SeenByModal';
import { ReactionDetailsModal } from '@/components/chat/ReactionDetailsModal';
import { DirectMessageBubble } from '@/components/chat/DirectMessageBubble';
import { GroupMessageBubble } from '@/components/chat/GroupMessageBubble';
import { DirectChatInput } from '@/components/chat/DirectChatInput';
import { GroupChatInput } from '@/components/chat/GroupChatInput';
import { ChatContextMenu } from '@/components/chat/ChatContextMenu';

interface ChatPageProps { isEmbedded?: boolean; }
type TabType = 'direct' | 'group';

export function ChatPage({ isEmbedded = false }: ChatPageProps) {
    const { user } = useAuth();
    const navigate = useNavigate();

    // ── Tab ─────────────────────────────────────────────────────────────────────
    const [activeTab, setActiveTab] = useState<TabType>('direct');

    // ── Direct chat state ────────────────────────────────────────────────────────
    const [activeConversationId, setActiveConversationId] = useState<string | null>(null);
    const [messageText, setMessageText] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [userSearchTerm, setUserSearchTerm] = useState('');
    const [showUserSearch, setShowUserSearch] = useState(false);
    const [replyingTo, setReplyingTo] = useState<any>(null);
    const [editingMessage, setEditingMessage] = useState<any>(null);
    const [hoveredMessageId, setHoveredMessageId] = useState<any>(null);
    const [contextMenuMsg, setContextMenuMsg] = useState<any>(null);
    const [selectedImage, setSelectedImage] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const [isUploadingImage, setIsUploadingImage] = useState(false);

    // ── Group chat state ─────────────────────────────────────────────────────────
    const [groupMsgText, setGroupMsgText] = useState('');
    const [groupReplyingTo, setGroupReplyingTo] = useState<any>(null);
    const [groupEditingMsg, setGroupEditingMsg] = useState<any>(null);
    const [groupHoveredId, setGroupHoveredId] = useState<any>(null);
    const [groupContextMsg, setGroupContextMsg] = useState<any>(null);
    const [groupSelectedImage, setGroupSelectedImage] = useState<File | null>(null);
    const [groupImagePreview, setGroupImagePreview] = useState<string | null>(null);
    const [groupIsUploadingImage, setGroupIsUploadingImage] = useState(false);

    // ── Modals ───────────────────────────────────────────────────────────────────
    const [previewAvatar, setPreviewAvatar] = useState<{ url: string | null; name: string } | null>(null);
    const [seenByMessageId, setSeenByMessageId] = useState<string | null>(null);
    const [reactingMsg, setReactingMsg] = useState<{ id: any; isGroup: boolean } | null>(null);

    // ── Wallpaper ────────────────────────────────────────────────────────────────
    const [isUploadingWallpaper, setIsUploadingWallpaper] = useState(false);
    const wallpaperInputRef = useRef<HTMLInputElement>(null);

    // ── Voice note state — direct ────────────────────────────────────────────────
    const [isRecording, setIsRecording] = useState(false);
    const [recordingTime, setRecordingTime] = useState(0);
    const [pendingAudioBlob, setPendingAudioBlob] = useState<Blob | null>(null);
    const [pendingAudioUrl, setPendingAudioUrl] = useState<string | null>(null);
    const [isSendingAudio, setIsSendingAudio] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const recordingTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);

    // ── Voice note state — group ─────────────────────────────────────────────────
    const [grpIsRecording, setGrpIsRecording] = useState(false);
    const [grpRecordingTime, setGrpRecordingTime] = useState(0);
    const [grpPendingAudioBlob, setGrpPendingAudioBlob] = useState<Blob | null>(null);
    const [grpPendingAudioUrl, setGrpPendingAudioUrl] = useState<string | null>(null);
    const [grpIsSendingAudio, setGrpIsSendingAudio] = useState(false);
    const grpMediaRecorderRef = useRef<MediaRecorder | null>(null);
    const grpRecordingTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const grpAudioChunksRef = useRef<Blob[]>([]);

    // ── Misc refs ────────────────────────────────────────────────────────────────
    const scrollRef = useRef<HTMLDivElement>(null);
    const groupScrollRef = useRef<HTMLDivElement>(null);
    const longPressTimer = useRef<any>(null);
    const isLongPress = useRef(false);
    const [keyboardOffset, setKeyboardOffset] = useState(0);

    // ── Queries ──────────────────────────────────────────────────────────────────
    const conversations = useQuery(api.chat.getConversations, user ? { userId: user._id } : 'skip');
    const messages = useQuery(
        api.chat.getMessages,
        activeConversationId && user
            ? { conversationId: activeConversationId as Id<'conversations'>, userId: user._id }
            : 'skip'
    );
    const chatContacts = useQuery(api.users.getChatContacts, user ? { userId: user._id } : 'skip');
    const globalWallpaper = useQuery(api.settings.getGlobalChatWallpaper);
    const chatImagesEnabled = useQuery(api.settings.getChatImagesEnabledForMembers);
    const chatVoiceNotesEnabled = useQuery(api.settings.getChatVoiceNotesEnabledForMembers);
    const communityGroup = useQuery(api.chat.getCommunityGroup);
    const groupMessages = useQuery(
        api.chat.getGroupMessages,
        communityGroup ? { groupId: communityGroup._id } : 'skip'
    );

    // ── Mutations ────────────────────────────────────────────────────────────────
    const sendMessage = useMutation(api.chat.sendMessage);
    const markAsRead = useMutation(api.chat.markAsRead);
    const editMessage = useMutation(api.chat.editMessage);
    const deleteMessage = useMutation(api.chat.deleteMessage);
    const toggleReaction = useMutation(api.chat.toggleReaction);
    const updateChatWallpaper = useMutation(api.users.updateChatWallpaper);
    const getOrCreateCommunityGroup = useMutation(api.chat.getOrCreateCommunityGroup);
    const sendGroupMessage = useMutation(api.chat.sendGroupMessage);
    const editGroupMessage = useMutation(api.chat.editGroupMessage);
    const deleteGroupMessage = useMutation(api.chat.deleteGroupMessage);
    const toggleGroupReaction = useMutation(api.chat.toggleGroupReaction);
    const toggleGroupLock = useMutation(api.chat.toggleGroupLock);
    const recordGroupMessageView = useMutation(api.chat.recordGroupMessageView);
    const markGroupAsRead = useMutation(api.chat.markGroupAsRead);
    const uploadAudio = useAction(api.audio.uploadAudio);

    const isAdmin = user?.role === 'admin' || user?.role === 'super_admin';
    const canSendImages = isAdmin || !!chatImagesEnabled;
    const canSendVoiceNotes = isAdmin || chatVoiceNotesEnabled !== false;

    // ── Effects ──────────────────────────────────────────────────────────────────
    useEffect(() => {
        const vv = window.visualViewport;
        if (!vv) return;
        const handler = () => {
            const offset = Math.max(0, window.innerHeight - vv!.height - vv!.offsetTop);
            setKeyboardOffset(offset);
            if (offset > 0) setTimeout(() => {
                scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
                groupScrollRef.current?.scrollTo({ top: groupScrollRef.current.scrollHeight, behavior: 'smooth' });
            }, 100);
        };
        vv.addEventListener('resize', handler);
        vv.addEventListener('scroll', handler);
        return () => { vv.removeEventListener('resize', handler); vv.removeEventListener('scroll', handler); };
    }, []);

    useEffect(() => { if (user && communityGroup === null) getOrCreateCommunityGroup({ userId: user._id }).catch(console.error); }, [communityGroup, user]);
    useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }, [messages, activeConversationId, replyingTo]);
    useEffect(() => { if (groupScrollRef.current) groupScrollRef.current.scrollTop = groupScrollRef.current.scrollHeight; }, [groupMessages, activeTab]);

    useEffect(() => {
        if (!groupMessages || !user || activeTab !== 'group') return;
        const observer = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    const msgId = (entry.target as HTMLElement).dataset.msgid;
                    const senderId = (entry.target as HTMLElement).dataset.senderid;
                    if (msgId && senderId && senderId !== user._id) {
                        recordGroupMessageView({ messageId: msgId as Id<'groupMessages'>, userId: user._id }).catch(() => { });
                    }
                }
            });
        }, { threshold: 0.5 });
        document.querySelectorAll('[data-groupmsg]').forEach((el) => observer.observe(el));
        return () => observer.disconnect();
    }, [groupMessages, user, activeTab]);

    useEffect(() => {
        if (activeConversationId && user) markAsRead({ conversationId: activeConversationId as Id<'conversations'>, userId: user._id });
    }, [activeConversationId, messages, user]);
    useEffect(() => {
        if (activeTab === 'group' && user) markGroupAsRead({ userId: user._id });
    }, [activeTab, groupMessages, user]);

    // ── Wallpaper ────────────────────────────────────────────────────────────────
    const handleWallpaperUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !user) return;
        setIsUploadingWallpaper(true);
        try {
            const url = await uploadToImageKit(file, 'announcements');
            await updateChatWallpaper({ userId: user._id, wallpaperUrl: url });
        } catch { alert('Failed to update wallpaper'); }
        finally { setIsUploadingWallpaper(false); }
    };

    // ── Direct send ──────────────────────────────────────────────────────────────
    const handleSendMessage = async () => {
        if ((!messageText.trim() && !selectedImage) || !activeConversationId || !user) return;
        try {
            if (editingMessage) {
                await editMessage({ messageId: editingMessage._id, userId: user._id, newText: messageText });
                setEditingMessage(null);
            } else {
                const activeConv = conversations?.find((c: any) => c._id === activeConversationId);
                const recipientId = activeConv?.participantOne === user._id ? activeConv.participantTwo : activeConv?.participantOne;
                if (!recipientId) return;
                let imageUrl;
                if (selectedImage) { setIsUploadingImage(true); imageUrl = await uploadToImageKit(selectedImage, 'chat'); }
                await sendMessage({ senderId: user._id, recipientId, text: messageText, imageUrl, replyToId: replyingTo?._id });
                setReplyingTo(null); setSelectedImage(null); setImagePreview(null);
            }
            setMessageText('');
        } catch (err: any) { alert(err.message || 'Failed to send message'); }
        finally { setIsUploadingImage(false); }
    };

    // ── Group send ───────────────────────────────────────────────────────────────
    const handleSendGroupMessage = async () => {
        if ((!groupMsgText.trim() && !groupSelectedImage) || !communityGroup || !user) return;
        try {
            if (groupEditingMsg) {
                await editGroupMessage({ messageId: groupEditingMsg._id, userId: user._id, newText: groupMsgText });
                setGroupEditingMsg(null);
            } else {
                let imageUrl;
                if (groupSelectedImage) { setGroupIsUploadingImage(true); imageUrl = await uploadToImageKit(groupSelectedImage, 'chat'); }
                await sendGroupMessage({ groupId: communityGroup._id, senderId: user._id, text: groupMsgText, imageUrl, replyToId: groupReplyingTo?._id });
                setGroupReplyingTo(null); setGroupSelectedImage(null); setGroupImagePreview(null);
            }
            setGroupMsgText('');
        } catch (err: any) { alert(err.message || 'Failed to send group message'); }
        finally { setGroupIsUploadingImage(false); }
    };

    // ── Start conversation ───────────────────────────────────────────────────────
    const handleStartConversation = async (recipientId: string) => {
        if (!user) return;
        try {
            const conversationId = await sendMessage({ senderId: user._id, recipientId: recipientId as Id<'users'>, text: 'Hi!' });
            setActiveConversationId(conversationId); setShowUserSearch(false); setUserSearchTerm('');
        } catch (err: any) { alert(err.message || 'Failed to start conversation'); }
    };

    // ── Voice note — direct ──────────────────────────────────────────────────────
    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const mr = new MediaRecorder(stream);
            audioChunksRef.current = [];
            mr.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
            mr.onstop = () => {
                const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
                setPendingAudioBlob(blob); setPendingAudioUrl(URL.createObjectURL(blob));
                stream.getTracks().forEach(t => t.stop());
            };
            mr.start(); mediaRecorderRef.current = mr;
            setIsRecording(true); setRecordingTime(0);
            recordingTimerRef.current = setInterval(() => setRecordingTime(t => t + 1), 1000);
        } catch { alert('Microphone permission denied.'); }
    };
    const stopRecording = () => { if (recordingTimerRef.current) clearInterval(recordingTimerRef.current); mediaRecorderRef.current?.stop(); setIsRecording(false); };
    const cancelRecording = () => { stopRecording(); setPendingAudioBlob(null); setPendingAudioUrl(null); setRecordingTime(0); };
    const sendAudioMessage = async () => {
        if (!pendingAudioBlob || !activeConversationId || !user) return;
        setIsSendingAudio(true);
        try {
            const activeConv = conversations?.find((c: any) => c._id === activeConversationId);
            const recipientId = activeConv?.participantOne === user._id ? activeConv.participantTwo : activeConv?.participantOne;
            if (!recipientId) return;
            const reader = new FileReader();
            reader.readAsDataURL(pendingAudioBlob);
            reader.onloadend = async () => {
                const dataUri = reader.result as string;
                const result = await uploadAudio({ fileBase64: dataUri, isChat: true });
                await sendMessage({ senderId: user._id, recipientId: recipientId as Id<'users'>, text: '🎤 Voice Note', audioUrl: result.audioUrl, audioDuration: result.audioDuration ?? recordingTime });
                setPendingAudioBlob(null); setPendingAudioUrl(null); setRecordingTime(0);
            };
        } catch (e: any) { alert(e.message || 'Failed to send voice note'); }
        finally { setIsSendingAudio(false); }
    };

    // ── Voice note — group ───────────────────────────────────────────────────────
    const grpStartRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const mr = new MediaRecorder(stream);
            grpAudioChunksRef.current = [];
            mr.ondataavailable = (e) => { if (e.data.size > 0) grpAudioChunksRef.current.push(e.data); };
            mr.onstop = () => {
                const blob = new Blob(grpAudioChunksRef.current, { type: 'audio/webm' });
                setGrpPendingAudioBlob(blob); setGrpPendingAudioUrl(URL.createObjectURL(blob));
                stream.getTracks().forEach(t => t.stop());
            };
            mr.start(); grpMediaRecorderRef.current = mr;
            setGrpIsRecording(true); setGrpRecordingTime(0);
            grpRecordingTimerRef.current = setInterval(() => setGrpRecordingTime(t => t + 1), 1000);
        } catch { alert('Microphone permission denied.'); }
    };
    const grpStopRecording = () => { if (grpRecordingTimerRef.current) clearInterval(grpRecordingTimerRef.current); grpMediaRecorderRef.current?.stop(); setGrpIsRecording(false); };
    const grpCancelRecording = () => { grpStopRecording(); setGrpPendingAudioBlob(null); setGrpPendingAudioUrl(null); setGrpRecordingTime(0); };
    const grpSendAudioMessage = async () => {
        if (!grpPendingAudioBlob || !communityGroup || !user) return;
        setGrpIsSendingAudio(true);
        try {
            const reader = new FileReader();
            reader.readAsDataURL(grpPendingAudioBlob);
            reader.onloadend = async () => {
                const dataUri = reader.result as string;
                const result = await uploadAudio({ fileBase64: dataUri, isChat: true });
                await sendGroupMessage({ groupId: communityGroup._id, senderId: user._id, text: '🎤 Voice Note', audioUrl: result.audioUrl, audioDuration: result.audioDuration ?? grpRecordingTime });
                setGrpPendingAudioBlob(null); setGrpPendingAudioUrl(null); setGrpRecordingTime(0);
            };
        } catch (e: any) { alert(e.message || 'Failed to send voice note'); }
        finally { setGrpIsSendingAudio(false); }
    };

    // ── Long press ───────────────────────────────────────────────────────────────
    const handleTouchStart = (msg: any, isGroup = false) => {
        isLongPress.current = false;
        longPressTimer.current = setTimeout(() => {
            isLongPress.current = true;
            if (isGroup) setGroupContextMsg(msg); else setContextMenuMsg(msg);
        }, 500);
    };
    const handleTouchEnd = () => { if (longPressTimer.current) { clearTimeout(longPressTimer.current); longPressTimer.current = null; } };

    // ── Filters ──────────────────────────────────────────────────────────────────
    const filteredConversations = conversations?.filter((c: any) => c.otherUser?.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredContacts = chatContacts?.filter((u: any) => u._id !== user?._id && u.name.toLowerCase().includes(userSearchTerm.toLowerCase()));
    const activeConversation = conversations?.find((c: any) => c._id === activeConversationId);

    if (!user) { navigate('/login'); return null; }

    // ── Unread counts ────────────────────────────────────────────────────────────
    const directUnread = conversations?.reduce((sum: number, c: any) => sum + (c.unreadCount || 0), 0) || 0;
    let groupUnread = 0;
    if (communityGroup && groupMessages && user) {
        const lastViewed = user.lastViewedCommunityChatAt ?? 0;
        const reactionCount = groupMessages.reduce((sum: number, m: any) => sum + (m.reactions?.filter((r: any) => r.userId !== user._id && r.createdAt > lastViewed).length || 0), 0);
        const newMsgsCount = groupMessages.filter((m: any) => m.senderId !== user._id && m.createdAt > lastViewed).length;
        groupUnread = newMsgsCount + reactionCount;
    }

    return (
        <div
            className={`${isEmbedded ? 'relative w-full h-full' : 'fixed inset-0 z-[100]'} bg-light-bg dark:bg-dark-bg flex flex-col`}
            style={{ paddingBottom: keyboardOffset }}
        >
            {/* ── Global Modals ─────────────────────────────────────────────────── */}
            <SeenByModal messageId={seenByMessageId} onClose={() => setSeenByMessageId(null)} />
            <ReactionDetailsModal reactingMsg={reactingMsg} onClose={() => setReactingMsg(null)} />
            <AvatarPreviewModal previewAvatar={previewAvatar} onClose={() => setPreviewAvatar(null)} />

            <input type="file" ref={wallpaperInputRef} onChange={handleWallpaperUpload} className="hidden" accept="image/*" />

            <style>{`
                .custom-thin-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-thin-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-thin-scrollbar::-webkit-scrollbar-thumb { background: #9ca3af; border-radius: 10px; }
                .dark .custom-thin-scrollbar::-webkit-scrollbar-thumb { background: #4b5563; }
                body { overscroll-behavior: none; }
                .scrollbar-none::-webkit-scrollbar { display: none; }
                .scrollbar-none { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>

            <div className="flex-1 flex overflow-hidden">
                {/* ── SIDEBAR ──────────────────────────────────────────────────── */}
                <div className={`${(activeConversationId && activeTab === 'direct') ? 'hidden md:flex' : 'flex'} md:w-[380px] flex-col border-r border-light-border dark:border-dark-border bg-white dark:bg-dark-card flex-shrink-0 w-full relative`}>

                    {/* Sidebar Header */}
                    <div className="p-4 border-b border-light-border dark:border-dark-border bg-white dark:bg-dark-card flex-shrink-0">
                        <div className="flex items-center justify-between mb-3">
                            <div className="flex items-center gap-3">
                                <button onClick={() => navigate('/feed')} className="md:hidden p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 -ml-2">
                                    <ArrowLeft className="w-5 h-5" />
                                </button>
                                <h1 className="text-xl md:text-2xl font-bold text-light-text dark:text-dark-text">Messages</h1>
                            </div>
                        </div>

                        {/* Tab switcher */}
                        <div className="flex gap-1 p-1 bg-gray-100 dark:bg-gray-800 rounded-xl">
                            <button
                                onClick={() => setActiveTab('direct')}
                                className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-xs font-bold transition-all relative ${activeTab === 'direct' ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-sm' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
                            >
                                <MessageCircle className="w-4 h-4" /> Direct
                                {directUnread > 0 && (
                                    <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 bg-primary-500 text-white text-[9px] flex items-center justify-center rounded-full border border-white dark:border-gray-800 font-bold shadow-sm animate-bounce">
                                        {directUnread > 9 ? '9+' : directUnread}
                                    </span>
                                )}
                            </button>
                            <button
                                onClick={() => { setActiveTab('group'); if (!communityGroup && user) getOrCreateCommunityGroup({ userId: user._id }); }}
                                className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-xs font-bold transition-all relative ${activeTab === 'group' ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-sm' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
                            >
                                <Users className="w-4 h-4" /> Community
                                {groupUnread > 0 && (
                                    <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 bg-green-500 text-white text-[9px] flex items-center justify-center rounded-full border border-white dark:border-gray-800 font-bold shadow-sm animate-bounce">
                                        {groupUnread > 9 ? '9+' : groupUnread}
                                    </span>
                                )}
                                {communityGroup?.isLocked && <Lock className="w-3 h-3 text-amber-500" />}
                            </button>
                        </div>
                    </div>

                    {/* ── DIRECT TAB ─────────────────────────────────────────────── */}
                    {activeTab === 'direct' && (
                        <>
                            {/* Search */}
                            <div className="p-3 border-b border-light-border dark:border-dark-border flex-shrink-0 bg-white dark:bg-dark-card">
                                <div className="relative">
                                    <Search className="w-4 h-4 absolute left-3 top-3 text-gray-400" />
                                    <input
                                        type="text" placeholder="Search conversations..."
                                        value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                                        className="w-full pl-10 pr-4 py-2 rounded-xl bg-gray-100 dark:bg-gray-800 border border-transparent text-sm focus:ring-2 focus:ring-primary-500 transition-all"
                                    />
                                </div>
                            </div>

                            {/* New chat overlay */}
                            {showUserSearch && (
                                <div className="absolute inset-x-0 top-0 bottom-[60px] z-20 bg-white dark:bg-dark-card flex flex-col">
                                    <div className="p-4 border-b border-light-border dark:border-dark-border flex-shrink-0">
                                        <div className="flex items-center gap-3 mb-3">
                                            <button onClick={() => setShowUserSearch(false)} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800">
                                                <ArrowLeft className="w-5 h-5" />
                                            </button>
                                            <h2 className="text-lg font-bold">New Message</h2>
                                        </div>
                                        {!isAdmin && (
                                            <p className="text-xs text-gray-500 mb-3 bg-gray-50 dark:bg-gray-800 px-3 py-2 rounded-lg">
                                                💡 You can message <strong>admins</strong> and <strong>members you follow</strong>.
                                            </p>
                                        )}
                                        <div className="relative">
                                            <Search className="w-4 h-4 absolute left-3 top-3 text-gray-400" />
                                            <input
                                                type="text" placeholder="Search contacts..."
                                                value={userSearchTerm} onChange={(e) => setUserSearchTerm(e.target.value)}
                                                className="w-full pl-10 pr-4 py-2 rounded-xl bg-gray-100 dark:bg-gray-800 border border-transparent text-sm focus:ring-2 focus:ring-primary-500 transition-all"
                                                autoFocus
                                            />
                                        </div>
                                    </div>
                                    <div className="flex-1 overflow-y-auto custom-thin-scrollbar">
                                        {!chatContacts ? (
                                            <div className="p-4"><ChatListSkeleton count={8} /></div>
                                        ) : filteredContacts?.length === 0 ? (
                                            <div className="flex flex-col items-center justify-center h-full p-8 text-center text-gray-500 text-sm">
                                                <MessageSquare className="w-12 h-12 mb-3 text-gray-300" />
                                                <p>No contacts found.</p>
                                                {!isAdmin && <p className="text-xs mt-2">Follow other members to chat with them.</p>}
                                            </div>
                                        ) : (
                                            filteredContacts?.map((u: any) => (
                                                <div
                                                    key={u._id}
                                                    onClick={() => handleStartConversation(u._id)}
                                                    className="flex items-center gap-3 p-4 hover:bg-gray-50 dark:hover:bg-gray-800 cursor-pointer transition-colors border-b border-light-border/50 dark:border-dark-border/50"
                                                >
                                                    <div onClick={(e) => { e.stopPropagation(); setPreviewAvatar({ url: u.avatarUrl, name: u.name }); }}>
                                                        <Avatar src={u.avatarUrl} alt={u.name} className="w-12 h-12 cursor-pointer" />
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <div className="flex items-center gap-1.5">
                                                            <h4 className="font-semibold text-sm text-gray-900 dark:text-gray-100 truncate">{u.name}</h4>
                                                            {(u.role === 'admin' || u.role === 'super_admin') && (
                                                                <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-primary-100 dark:bg-primary-900/30 text-primary-600 uppercase">
                                                                    {u.role === 'super_admin' ? 'Super Admin' : 'Admin'}
                                                                </span>
                                                            )}
                                                        </div>
                                                        <p className="text-xs text-gray-500 truncate">{u.email}</p>
                                                    </div>
                                                </div>
                                            ))
                                        )}
                                    </div>
                                </div>
                            )}

                            {/* Conversation list */}
                            <div className="flex-1 overflow-y-auto custom-thin-scrollbar">
                                {!conversations ? (
                                    <div className="p-4"><ChatListSkeleton count={6} /></div>
                                ) : filteredConversations?.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-full text-center p-8">
                                        <MessageSquare className="w-16 h-16 text-gray-300 dark:text-gray-700 mb-4" />
                                        <p className="text-gray-500 text-sm">No conversations yet</p>
                                        <button
                                            onClick={() => setShowUserSearch(true)}
                                            className="mt-4 px-4 py-2 bg-primary-500 text-white rounded-xl text-sm font-semibold hover:bg-primary-600 transition-colors"
                                        >
                                            Start a conversation
                                        </button>
                                    </div>
                                ) : (
                                    filteredConversations?.map((conv: any) => (
                                        <div
                                            key={conv._id}
                                            onClick={() => setActiveConversationId(conv._id)}
                                            className={`flex items-center gap-3 p-4 cursor-pointer transition-colors border-b border-light-border/50 dark:border-dark-border/50 ${activeConversationId === conv._id ? 'bg-primary-50 dark:bg-primary-900/20' : 'hover:bg-gray-50 dark:hover:bg-gray-800'}`}
                                        >
                                            <div onClick={(e) => { e.stopPropagation(); setPreviewAvatar({ url: conv.otherUser?.avatarUrl, name: conv.otherUser?.name || 'User' }); }}>
                                                <Avatar src={conv.otherUser?.avatarUrl} alt={conv.otherUser?.name || 'User'} className="w-12 h-12 cursor-pointer" />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex justify-between items-baseline mb-1">
                                                    <h4 className="font-semibold text-sm text-gray-900 dark:text-gray-100 truncate">{conv.otherUser?.name}</h4>
                                                    <span className="text-[10px] text-gray-500 ml-2 flex-shrink-0">{formatDistanceToNow(conv.updatedAt, { addSuffix: false })}</span>
                                                </div>
                                                <p className={`text-xs truncate ${(conv.unreadCount || 0) > 0 ? 'font-bold text-gray-900 dark:text-gray-100' : 'text-gray-500'}`}>
                                                    {conv.lastMessageSenderId === user?._id ? 'You: ' : ''}{conv.lastMessageText || 'Start a conversation'}
                                                </p>
                                            </div>
                                            {(conv.unreadCount || 0) > 0 && (
                                                <div className="min-w-[20px] h-5 px-1.5 bg-primary-500 rounded-full flex items-center justify-center text-[10px] text-white font-bold animate-pulse">
                                                    {conv.unreadCount}
                                                </div>
                                            )}
                                        </div>
                                    ))
                                )}
                            </div>

                            {/* Sidebar footer nav */}
                            <div className="flex-shrink-0 bg-white dark:bg-dark-card border-t border-light-border dark:border-dark-border py-2 px-6 flex justify-center gap-10 md:gap-16 items-center">
                                <button
                                    onClick={() => { if (showUserSearch) setShowUserSearch(false); else if (activeConversationId) setActiveConversationId(null); }}
                                    className={`flex flex-col items-center gap-1 ${!showUserSearch ? 'text-primary-500' : 'text-light-muted dark:text-dark-muted hover:text-primary-500'}`}
                                >
                                    <MessageCircle className="w-6 h-6 md:w-7 md:h-7 fill-current" />
                                    <span className="text-[10px] font-bold">Chats</span>
                                </button>
                                <button
                                    onClick={() => setShowUserSearch(true)}
                                    className={`flex flex-col items-center gap-1 -mt-6 ${showUserSearch ? 'text-primary-500' : 'text-light-muted dark:text-dark-muted hover:text-primary-500'}`}
                                >
                                    <div className={`w-12 h-12 md:w-14 md:h-14 rounded-full flex items-center justify-center text-white shadow-lg ${showUserSearch ? 'bg-primary-600 ring-4 ring-primary-100' : 'bg-primary-500 shadow-primary-500/30'}`}>
                                        <MessageSquare className="w-5 h-5 md:w-6 md:h-6" />
                                    </div>
                                    <span className="text-[10px] font-bold mt-1">New Chat</span>
                                </button>
                                <Link to="/feed" className="flex flex-col items-center gap-1 text-light-muted dark:text-dark-muted hover:text-primary-500">
                                    <Sparkles className="w-6 h-6 md:w-7 md:h-7" />
                                    <span className="text-[10px] font-bold">Feed</span>
                                </Link>
                            </div>
                        </>
                    )}

                    {/* ── GROUP TAB ──────────────────────────────────────────────── */}
                    {activeTab === 'group' && (
                        <div className="flex-1 flex flex-col overflow-hidden">
                            {/* Group header */}
                            <div className="p-3 border-b border-light-border dark:border-dark-border bg-white dark:bg-dark-card flex items-center gap-3 flex-shrink-0">
                                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold text-lg flex-shrink-0">
                                    <Users className="w-5 h-5" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h3 className="font-bold text-sm text-gray-900 dark:text-gray-100">{communityGroup?.name || 'Community'}</h3>
                                    <p className="text-xs text-gray-500 truncate">{communityGroup?.description || 'All members'}</p>
                                </div>
                                {isAdmin && communityGroup && (
                                    <button
                                        onClick={async () => { if (!communityGroup || !user || !isAdmin) return; await toggleGroupLock({ groupId: communityGroup._id, adminId: user._id, locked: !communityGroup.isLocked }); }}
                                        className={`p-2 rounded-lg transition-all text-sm font-bold flex items-center gap-1 ${communityGroup.isLocked ? 'bg-amber-100 dark:bg-amber-900/30 text-amber-600 hover:bg-amber-200' : 'bg-gray-100 dark:bg-gray-800 text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700'}`}
                                        title={communityGroup.isLocked ? 'Unlock group' : 'Lock group'}
                                    >
                                        {communityGroup.isLocked ? <Lock className="w-4 h-4" /> : <Unlock className="w-4 h-4" />}
                                    </button>
                                )}
                            </div>

                            {communityGroup?.isLocked && (
                                <div className="px-4 py-2 bg-amber-50 dark:bg-amber-900/20 border-b border-amber-200 dark:border-amber-800 flex items-center gap-2 text-xs text-amber-700 dark:text-amber-400 font-medium">
                                    <Lock className="w-3 h-3" /> Group is locked — only admins can send messages
                                </div>
                            )}

                            {/* Group messages */}
                            <div
                                ref={groupScrollRef}
                                className="flex-1 p-4 overflow-y-auto custom-thin-scrollbar overflow-x-hidden relative"
                                style={{ backgroundImage: globalWallpaper ? `url(${globalWallpaper})` : undefined, backgroundSize: 'cover', backgroundPosition: 'center' }}
                            >
                                {globalWallpaper && <div className="absolute inset-0 bg-white/70 dark:bg-black/60 pointer-events-none z-0" />}
                                <div className="relative z-10 space-y-1">
                                    {!groupMessages ? <MessagesSkeleton /> : groupMessages.length === 0 ? (
                                        <div className="flex items-center justify-center h-full pt-20">
                                            <div className="text-center text-gray-500 text-sm">
                                                <Users className="w-12 h-12 mx-auto mb-3 text-gray-300" />
                                                <p>No messages yet. Say hi to the community! 👋</p>
                                            </div>
                                        </div>
                                    ) : groupMessages.map((msg: any) => (
                                        <GroupMessageBubble
                                            key={msg._id}
                                            msg={msg}
                                            isMe={msg.senderId === user._id}
                                            groupHoveredId={groupHoveredId}
                                            seenByMessageId={seenByMessageId}
                                            onMouseEnter={() => setGroupHoveredId(msg._id)}
                                            onMouseLeave={() => setGroupHoveredId(null)}
                                            onTouchStart={() => handleTouchStart(msg, true)}
                                            onTouchEnd={handleTouchEnd}
                                            onContextMenu={() => setGroupContextMsg(msg)}
                                            onReact={() => setReactingMsg({ id: msg._id, isGroup: true })}
                                            onToggleSeen={() => setSeenByMessageId(seenByMessageId === msg._id ? null : msg._id)}
                                            onReply={() => setGroupReplyingTo(msg)}
                                        />
                                    ))}
                                </div>
                            </div>

                            <GroupChatInput
                                groupMsgText={groupMsgText}
                                setGroupMsgText={setGroupMsgText}
                                groupEditingMsg={groupEditingMsg}
                                groupReplyingTo={groupReplyingTo}
                                onCancelReplyEdit={() => { setGroupReplyingTo(null); setGroupEditingMsg(null); setGroupMsgText(''); }}
                                onSend={handleSendGroupMessage}
                                onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendGroupMessage(); } }}
                                groupImagePreview={groupImagePreview}
                                groupIsUploadingImage={groupIsUploadingImage}
                                onImageSelect={(e) => { const f = e.target.files?.[0]; if (f) { setGroupSelectedImage(f); setGroupImagePreview(URL.createObjectURL(f)); } }}
                                onClearImage={() => { setGroupSelectedImage(null); setGroupImagePreview(null); }}
                                canSendImages={canSendImages}
                                grpIsRecording={grpIsRecording}
                                grpRecordingTime={grpRecordingTime}
                                grpPendingAudioUrl={grpPendingAudioUrl}
                                grpIsSendingAudio={grpIsSendingAudio}
                                onStartRecording={grpStartRecording}
                                onStopRecording={grpStopRecording}
                                onCancelRecording={grpCancelRecording}
                                onSendAudio={grpSendAudioMessage}
                                canSendVoiceNotes={canSendVoiceNotes}
                                isLocked={!!communityGroup?.isLocked}
                                isAdmin={isAdmin}
                                groupScrollRef={groupScrollRef}
                            />

                            {/* Group Context Menu */}
                            {groupContextMsg && (
                                <ChatContextMenu
                                    msg={groupContextMsg}
                                    userId={user._id}
                                    isGroup
                                    onClose={() => setGroupContextMsg(null)}
                                    onReact={(emoji) => toggleGroupReaction({ messageId: groupContextMsg._id, userId: user._id, emoji })}
                                    onReply={() => setGroupReplyingTo(groupContextMsg)}
                                    onEdit={() => { setGroupEditingMsg(groupContextMsg); setGroupMsgText(groupContextMsg.text); }}
                                    onDelete={() => deleteGroupMessage({ messageId: groupContextMsg._id, userId: user._id })}
                                    onSeenBy={() => setSeenByMessageId(groupContextMsg._id)}
                                />
                            )}
                        </div>
                    )}
                </div>

                {/* ── DIRECT CHAT WINDOW ──────────────────────────────────────── */}
                {activeTab === 'direct' && (
                    <div
                        className={`${activeConversationId ? 'flex' : 'hidden md:flex'} flex-1 flex-col bg-gray-50 dark:bg-gray-900 ${activeConversationId ? 'fixed inset-0 md:relative z-[200] md:z-auto' : ''} relative overflow-hidden`}
                        style={activeConversationId ? { bottom: keyboardOffset } : undefined}
                    >
                        {/* Wallpaper */}
                        {(user?.chatWallpaperUrl || globalWallpaper) && (
                            <div
                                className="absolute inset-0 z-0 bg-cover bg-center opacity-30 dark:opacity-20 pointer-events-none"
                                style={{ backgroundImage: `url(${user?.chatWallpaperUrl || globalWallpaper})`, filter: 'blur(3px)' }}
                            />
                        )}

                        {activeConversationId && activeConversation ? (
                            <>
                                {/* Chat header */}
                                <div className="p-4 bg-white/90 dark:bg-dark-card/90 backdrop-blur-md border-b border-light-border dark:border-dark-border flex items-center gap-3 flex-shrink-0 z-10">
                                    <button onClick={() => setActiveConversationId(null)} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 -ml-2">
                                        <ArrowLeft className="w-5 h-5" />
                                    </button>
                                    <button
                                        className="rounded-full focus:outline-none cursor-pointer"
                                        onClick={() => setPreviewAvatar({ url: activeConversation!.otherUser?.avatarUrl ?? null, name: activeConversation!.otherUser?.name || 'User' })}
                                    >
                                        <Avatar src={activeConversation.otherUser?.avatarUrl} alt={activeConversation.otherUser?.name || 'User'} className="w-10 h-10" />
                                    </button>
                                    <div className="flex-1 min-w-0">
                                        <h3 className="font-semibold text-gray-900 dark:text-gray-100 truncate">{activeConversation.otherUser?.name}</h3>
                                        <p className="text-xs text-gray-500">{activeConversation.otherUser?.role || 'Member'}</p>
                                    </div>
                                    <button
                                        onClick={() => wallpaperInputRef.current?.click()}
                                        disabled={isUploadingWallpaper}
                                        className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-500 transition-colors"
                                        title="Change Chat Wallpaper"
                                    >
                                        {isUploadingWallpaper ? <Loader2 className="w-5 h-5 animate-spin" /> : <ImageIcon className="w-5 h-5" />}
                                    </button>
                                </div>

                                {/* Messages */}
                                <div className="flex-1 p-4 overflow-y-auto custom-thin-scrollbar overflow-x-hidden relative z-10" ref={scrollRef}>
                                    {!messages ? <MessagesSkeleton /> : messages.length === 0 ? (
                                        <div className="flex items-center justify-center h-full">
                                            <div className="text-center text-gray-500 text-sm">No messages yet. Say hi!</div>
                                        </div>
                                    ) : (
                                        <div className="space-y-4 pb-2">
                                            {messages.map((msg: any) => (
                                                <DirectMessageBubble
                                                    key={msg._id}
                                                    msg={msg}
                                                    isMe={msg.senderId === user._id}
                                                    hoveredMessageId={hoveredMessageId}
                                                    onMouseEnter={() => setHoveredMessageId(msg._id)}
                                                    onMouseLeave={() => setHoveredMessageId(null)}
                                                    onTouchStart={() => handleTouchStart(msg)}
                                                    onTouchEnd={handleTouchEnd}
                                                    onContextMenu={() => setContextMenuMsg(msg)}
                                                    onReply={() => setReplyingTo(msg)}
                                                    onReact={() => setReactingMsg({ id: msg._id, isGroup: false })}
                                                />
                                            ))}
                                        </div>
                                    )}
                                </div>

                                <DirectChatInput
                                    messageText={messageText}
                                    setMessageText={setMessageText}
                                    editingMessage={editingMessage}
                                    replyingTo={replyingTo}
                                    onCancelReplyEdit={() => { setReplyingTo(null); setEditingMessage(null); setMessageText(''); }}
                                    onSend={handleSendMessage}
                                    onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                                    imagePreview={imagePreview}
                                    isUploadingImage={isUploadingImage}
                                    onImageSelect={(e) => { const f = e.target.files?.[0]; if (f) { setSelectedImage(f); setImagePreview(URL.createObjectURL(f)); } }}
                                    onClearImage={() => { setSelectedImage(null); setImagePreview(null); }}
                                    canSendImages={canSendImages}
                                    isRecording={isRecording}
                                    recordingTime={recordingTime}
                                    pendingAudioUrl={pendingAudioUrl}
                                    isSendingAudio={isSendingAudio}
                                    onStartRecording={startRecording}
                                    onStopRecording={stopRecording}
                                    onCancelRecording={cancelRecording}
                                    onSendAudio={sendAudioMessage}
                                    canSendVoiceNotes={canSendVoiceNotes}
                                    scrollRef={scrollRef}
                                />

                                {/* Direct Context Menu */}
                                {contextMenuMsg && (
                                    <ChatContextMenu
                                        msg={contextMenuMsg}
                                        userId={user._id}
                                        onClose={() => setContextMenuMsg(null)}
                                        onReact={(emoji) => toggleReaction({ messageId: contextMenuMsg._id, userId: user!._id, emoji })}
                                        onReply={() => setReplyingTo(contextMenuMsg)}
                                        onEdit={() => { setEditingMessage(contextMenuMsg); setMessageText(contextMenuMsg.text); }}
                                        onDelete={() => deleteMessage({ messageId: contextMenuMsg._id, userId: user!._id })}
                                    />
                                )}
                            </>
                        ) : (
                            <div className="flex items-center justify-center h-full">
                                <div className="text-center">
                                    <MessageSquare className="w-24 h-24 text-gray-300 dark:text-gray-700 mx-auto mb-4" />
                                    <h3 className="text-lg font-semibold text-gray-600 dark:text-gray-400 mb-2">Select a conversation</h3>
                                    <p className="text-sm text-gray-500">Choose from your existing conversations or start a new one</p>
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {/* Group tab spacer panel on desktop */}
                {activeTab === 'group' && (
                    <div className="hidden md:flex flex-1 items-center justify-center bg-gray-50 dark:bg-gray-900">
                        <div className="text-center text-gray-400 dark:text-gray-600">
                            <Users className="w-20 h-20 mx-auto mb-4 opacity-40" />
                            <p className="font-medium">Join the conversation on the left</p>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}
