import { useState } from 'react';
import { Modal } from '../ui/Modal';
import { Button } from '../ui/Button';
import { AlertCircle } from 'lucide-react';

interface DisablePostModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (reason: string) => void;
    isLoading?: boolean;
}

export function DisablePostModal({ isOpen, onClose, onConfirm, isLoading }: DisablePostModalProps) {
    const [reason, setReason] = useState("Violates community guidelines");

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onConfirm(reason);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Disable Post">
            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="flex items-start gap-4 p-4 rounded-xl bg-red-500/5 border border-red-500/10">
                    <div className="p-2 bg-red-500/10 rounded-lg shrink-0">
                        <AlertCircle className="w-5 h-5 text-red-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-red-600 dark:text-red-400">Administrative Action</h4>
                        <p className="text-xs text-light-muted dark:text-dark-muted mt-0.5 leading-relaxed">
                            This will hide the post from the community feed. The author will receive a notification with your reason.
                        </p>
                    </div>
                </div>

                <div>
                    <label className="block text-sm font-medium mb-2 text-light-text dark:text-dark-text">
                        Reason for Disabling
                    </label>
                    <textarea
                        value={reason}
                        onChange={(e) => setReason(e.target.value)}
                        placeholder="Explain why this post is being disabled..."
                        className="w-full p-4 rounded-xl bg-light-card dark:bg-dark-card border-light-border dark:border-dark-border focus:border-red-500 focus:ring-0 text-sm resize-none"
                        rows={3}
                        required
                    />
                </div>

                <div className="flex justify-end gap-3 pt-2">
                    <Button
                        type="button"
                        variant="ghost"
                        onClick={onClose}
                    >
                        Cancel
                    </Button>
                    <Button
                        type="submit"
                        variant="danger"
                        isLoading={isLoading}
                        disabled={!reason.trim()}
                    >
                        Disable Post
                    </Button>
                </div>
            </form>
        </Modal>
    );
}
