import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { formatDistanceToNow } from 'date-fns';
import { Trash2, ChevronDown, Eye, Crown, Shield, X, CornerUpLeft } from 'lucide-react';
import { ChatImage } from './ChatImage';

interface GroupMessageBubbleProps {
    msg: any;
    isMe: boolean;
    groupHoveredId: any;
    seenByMessageId: string | null;
    onMouseEnter: () => void;
    onMouseLeave: () => void;
    onTouchStart: () => void;
    onTouchEnd: () => void;
    onContextMenu: () => void;
    onReact: () => void;
    onToggleSeen: () => void;
    onReply?: () => void;
}

export function GroupMessageBubble({
    msg, isMe, groupHoveredId,
    onMouseEnter, onMouseLeave,
    onTouchStart, onTouchEnd,
    onContextMenu, onReact, onToggleSeen, onReply,
}: GroupMessageBubbleProps) {

    const [imgModalSrc, setImgModalSrc] = useState<string | null>(null);
    const [showReplyHint, setShowReplyHint] = useState(false);

    if (msg.isDeleted) {
        return (
            <div className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div className="px-3 py-2 rounded-lg bg-gray-100 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 text-xs text-gray-500 italic flex items-center gap-2">
                    <Trash2 className="w-3 h-3" /> This message was deleted
                </div>
            </div>
        );
    }

    const roleColor = msg.senderRole === 'super_admin' ? 'text-amber-500' :
        msg.senderRole === 'admin' ? 'text-primary-500' : 'text-gray-500';

    const swipeThreshold = 60;

    const handleDragEnd = (_: any, info: any) => {
        const offset = info.offset.x;
        if (isMe && offset < -swipeThreshold) {
            onReply?.();
        } else if (!isMe && offset > swipeThreshold) {
            onReply?.();
        }
        setShowReplyHint(false);
    };

    return (
        <>
            {/* ── Image preview modal ───────────────────────────────────────── */}
            <AnimatePresence>
                {imgModalSrc && (
                    <motion.div
                        key="grp-img-modal"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md"
                        onClick={() => setImgModalSrc(null)}
                    >
                        <motion.div
                            initial={{ scale: 0.85, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.85, opacity: 0 }}
                            transition={{ type: 'spring', damping: 22, stiffness: 300 }}
                            className="relative max-w-[95vw] max-h-[90vh] rounded-2xl overflow-hidden shadow-2xl"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <img
                                src={imgModalSrc}
                                alt="Full preview"
                                className="max-w-full max-h-[85vh] object-contain rounded-2xl"
                            />
                            <button
                                onClick={() => setImgModalSrc(null)}
                                className="absolute top-3 right-3 p-2 bg-black/60 hover:bg-black/80 text-white rounded-full transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            <div
                className={`group relative flex ${isMe ? 'justify-end' : 'justify-start'} mb-3`}
                onMouseEnter={onMouseEnter}
                onMouseLeave={onMouseLeave}
                data-groupmsg="true"
                data-msgid={msg._id}
                data-senderid={msg.senderId}
            >
                {!isMe && (
                    <div className="flex-shrink-0 mr-2 mt-1">
                        <div className="w-7 h-7 rounded-full bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center text-white text-xs font-bold overflow-hidden">
                            {msg.senderAvatar
                                ? <img src={msg.senderAvatar} alt={msg.senderName} className="w-full h-full object-cover" />
                                : msg.senderName?.[0]}
                        </div>
                    </div>
                )}

                {/* Reply hint icon */}
                {showReplyHint && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.5 }}
                        animate={{ opacity: 1, scale: 1 }}
                        className={`absolute top-1/2 -translate-y-1/2 ${isMe ? 'right-full mr-2' : 'left-full ml-2'} text-primary-500`}
                    >
                        <CornerUpLeft className="w-5 h-5" />
                    </motion.div>
                )}

                <motion.div
                    drag="x"
                    dragConstraints={{ left: isMe ? -90 : 0, right: isMe ? 0 : 90 }}
                    dragElastic={0.15}
                    dragMomentum={false}
                    onDrag={(_: any, info: any) => {
                        const offset = info.offset.x;
                        const triggered = isMe ? offset < -swipeThreshold * 0.5 : offset > swipeThreshold * 0.5;
                        setShowReplyHint(triggered);
                    }}
                    onDragEnd={handleDragEnd}
                    whileDrag={{ scale: 1.02 }}
                    className="relative max-w-[78%] md:max-w-[65%] cursor-grab active:cursor-grabbing"
                    onTouchStart={onTouchStart}
                    onTouchEnd={onTouchEnd}
                >
                    {groupHoveredId === msg._id && (
                        <div className={`absolute top-0 ${isMe ? '-left-8' : '-right-8'} z-20`}>
                            <button
                                className="p-1 rounded-full bg-gray-200 dark:bg-gray-700 shadow-sm hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors"
                                onClick={(e) => { e.stopPropagation(); onContextMenu(); }}
                            >
                                <ChevronDown className="w-3 h-3 text-gray-600 dark:text-gray-300" />
                            </button>
                        </div>
                    )}

                    <div className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                        {!isMe && (
                            <span className={`text-[10px] font-bold mb-0.5 flex items-center gap-1 ${roleColor}`}>
                                {msg.senderRole === 'super_admin' && <Crown className="w-3 h-3" />}
                                {msg.senderRole === 'admin' && <Shield className="w-3 h-3" />}
                                {msg.senderName}
                            </span>
                        )}

                        {msg.replyTo && (
                            <div className={`mb-1 text-xs px-2 py-1 rounded bg-gray-200 dark:bg-gray-800 border-l-2 border-primary-500 w-full opacity-80 ${msg.replyTo.isDeleted ? 'italic' : ''}`}>
                                <span className="font-bold block text-primary-500">{msg.replyTo.senderName}</span>
                                {msg.replyTo.isDeleted ? 'Message deleted' : msg.replyTo.text?.length > 50 ? msg.replyTo.text.substring(0, 50) + '...' : msg.replyTo.text}
                            </div>
                        )}

                        <div
                            className={`px-4 py-2 rounded-2xl shadow-sm ${isMe ? 'bg-primary-500 text-white rounded-br-none' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-200 rounded-bl-none'}`}
                            style={{ wordBreak: 'break-word', overflowWrap: 'break-word' }}
                        >
                            {msg.imageUrl && (
                                <button
                                    className="block w-full rounded-xl overflow-hidden mb-1 focus:outline-none"
                                    onClick={() => setImgModalSrc(msg.imageUrl)}
                                >
                                    <ChatImage src={msg.imageUrl} alt="Chat attachment" />
                                </button>
                            )}
                            {msg.audioUrl ? (
                                <audio controls src={msg.audioUrl} className="max-w-[220px] h-8 outline-none" />
                            ) : (
                                msg.text && msg.text !== '🎤 Voice Note' && (
                                    <div className="text-sm whitespace-pre-wrap">{msg.text}</div>
                                )
                            )}
                            <div className={`text-[10px] mt-1 flex items-center justify-end gap-1.5 ${isMe ? 'text-white/70' : 'text-gray-400'}`}>
                                {msg.isEdited && <span className="opacity-70">(edited)</span>}
                                <span className="opacity-70">{formatDistanceToNow(msg.createdAt, { addSuffix: false })}</span>
                                {isMe && (
                                    <button
                                        onClick={(e) => { e.stopPropagation(); onToggleSeen(); }}
                                        className="flex items-center gap-0.5 opacity-75 hover:opacity-100 transition-opacity ml-0.5"
                                        title="See who viewed this"
                                    >
                                        <Eye className="w-3 h-3" />
                                        {msg._viewCount != null && msg._viewCount > 0 && (
                                            <span className="text-[9px] font-semibold">{msg._viewCount}</span>
                                        )}
                                    </button>
                                )}
                            </div>
                        </div>

                        {msg.reactions && msg.reactions.length > 0 && (
                            <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className={`flex -mt-2 ${isMe ? 'mr-2' : 'ml-2'} z-10 cursor-pointer`}>
                                {msg.reactions.map((r: any, i: number) => (
                                    <button
                                        key={i}
                                        onClick={(e) => { e.stopPropagation(); onReact(); }}
                                        className="text-xs bg-white dark:bg-gray-800 rounded-full shadow border border-gray-100 dark:border-gray-700 w-5 h-5 flex items-center justify-center hover:scale-110 transition-transform"
                                    >
                                        {r.emoji}
                                    </button>
                                ))}
                            </motion.div>
                        )}
                    </div>
                </motion.div>
            </div>
        </>
    );
}
