import { motion, AnimatePresence } from 'framer-motion';
import { Reply, Edit2, Trash2, Eye } from 'lucide-react';

const EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

interface Props {
    msg: any;
    userId: string;
    isGroup?: boolean;
    onClose: () => void;
    onReact: (emoji: string) => void;
    onReply: () => void;
    onEdit?: () => void;
    onDelete: () => void;
    onSeenBy?: () => void;
}

export function ChatContextMenu({ msg, userId, isGroup, onClose, onReact, onReply, onEdit, onDelete, onSeenBy }: Props) {
    if (!msg) return null;
    const isOwner = msg.senderId === userId;

    return (
        <AnimatePresence mode="wait">
            {/* Backdrop */}
            <motion.div
                key="ctx-backdrop"
                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                className="absolute inset-0 bg-black/50 z-[110]"
                onClick={onClose}
            />
            {/* Menu panel */}
            <motion.div
                key="ctx-menu"
                initial={{ opacity: 0, scale: 0.9, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.9, y: 20 }}
                transition={{ type: 'spring', damping: 22, stiffness: 320 }}
                className="absolute bottom-4 left-4 right-4 bg-white dark:bg-[#222] rounded-2xl p-2 shadow-2xl z-[120] flex flex-col gap-1"
            >
                {/* Emoji reactions */}
                <div className="flex items-center justify-around p-2 border-b border-gray-100 dark:border-gray-800 pb-3">
                    {EMOJIS.map(emoji => (
                        <button
                            key={emoji}
                            onClick={() => { onReact(emoji); onClose(); }}
                            className="text-2xl hover:scale-125 active:scale-110 transition-transform p-1"
                        >
                            {emoji}
                        </button>
                    ))}
                </div>

                <button
                    className="w-full text-left p-3 rounded-xl hover:bg-gray-100 dark:hover:bg-gray-700 active:bg-gray-200 dark:active:bg-gray-600 flex items-center gap-3 text-sm font-medium transition-colors"
                    onClick={() => { onReply(); onClose(); }}
                >
                    <Reply className="w-4 h-4" /> Reply
                </button>

                {isOwner && (
                    <>
                        {onEdit && !msg.audioUrl && (
                            <button
                                className="w-full text-left p-3 rounded-xl hover:bg-gray-100 dark:hover:bg-gray-700 active:bg-gray-200 dark:active:bg-gray-600 flex items-center gap-3 text-sm font-medium transition-colors"
                                onClick={() => { onEdit!(); onClose(); }}
                            >
                                <Edit2 className="w-4 h-4" /> Edit
                            </button>
                        )}
                        {isGroup && onSeenBy && (
                            <button
                                className="w-full text-left p-3 rounded-xl hover:bg-primary-50 dark:hover:bg-primary-900/20 text-primary-600 dark:text-primary-400 flex items-center gap-3 text-sm font-medium transition-colors"
                                onClick={() => { onSeenBy!(); onClose(); }}
                            >
                                <Eye className="w-4 h-4" /> Seen by
                            </button>
                        )}
                        <button
                            className="w-full text-left p-3 rounded-xl hover:bg-red-50 dark:hover:bg-red-900/20 active:bg-red-100 text-red-500 flex items-center gap-3 text-sm font-medium transition-colors"
                            onClick={() => { onDelete(); onClose(); }}
                        >
                            <Trash2 className="w-4 h-4" /> Delete
                        </button>
                    </>
                )}
            </motion.div>
        </AnimatePresence>
    );
}
