import React, { useState } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useAuth } from '@/hooks/useAuth';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Mail, Lock } from 'lucide-react';
import { motion } from 'framer-motion';
import { auth, googleProvider, signInWithPopup } from '@/lib/firebase';

export function LoginForm() {
    const navigate = useNavigate();
    const location = useLocation();
    const { login } = useAuth();
    const loginUser = useMutation(api.auth.loginUser);
    const googleLogin = useMutation(api.auth.googleLogin);

    const [formData, setFormData] = useState({
        email: '',
        password: '',
    });
    const [errors, setErrors] = useState<Record<string, string>>({});
    const [isLoading, setIsLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setErrors({});
        setIsLoading(true);

        try {
            const result = await loginUser({
                email: formData.email.toLowerCase().trim(),
                password: formData.password,
            });

            if (result?.success && result?.user) {
                login(result.user);
                const from = (location.state as any)?.from?.pathname || '/feed';
                navigate(from, { replace: true });
            } else {
                setErrors({ general: 'Invalid email or password' });
            }
        } catch (error) {
            setErrors({ general: 'Login failed. Please try again.' });
        } finally {
            setIsLoading(false);
        }
    };

    const handleGoogleLogin = async () => {
        setIsLoading(true);
        setErrors({});
        try {
            const result = await signInWithPopup(auth, googleProvider);
            const user = result.user;

            const convexUser = await googleLogin({
                email: user.email!,
                name: user.displayName || 'Anonymous',
                avatarUrl: user.photoURL || undefined
            });

            if (convexUser.success) {
                login(convexUser.user);
                if (convexUser.onboardingRequired) {
                    navigate('/member-onboarding', { state: { from: location.state?.from, isNew: true } });
                } else {
                    const from = (location.state as any)?.from?.pathname || '/feed';
                    navigate(from, { replace: true });
                }
            }
        } catch (error: any) {
            console.error("Google Login Error:", error);
            setErrors({ general: 'Google sign-in failed. Please try again.' });
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="w-full max-w-md mx-auto"
        >
            <Card glass>
                <CardHeader className="pt-8">
                    <div className="flex justify-center mb-4">
                        <img
                            src="https://ik.imagekit.io/h3qzmviwv/baptizo/Logo/premium-logo.png"
                            alt="Baptizo"
                            className="h-16 w-auto rounded-2xl shadow-xl"
                        />
                    </div>
                    <CardTitle className="text-center text-3xl">Welcome Back</CardTitle>
                    <p className="text-center text-light-muted dark:text-dark-muted mt-2">
                        Sign in to continue to Baptizo Community
                    </p>
                </CardHeader>
                <CardContent>
                    <div className="space-y-4">
                        <form onSubmit={handleSubmit} className="space-y-4">
                            {errors.general && (
                                <div className="p-3 rounded-lg bg-red-50 dark:bg-red-950 border border-red-200 dark:border-red-800">
                                    <p className="text-sm text-red-700 dark:text-red-300">{errors.general}</p>
                                </div>
                            )}

                            <Input
                                label="Email"
                                type="email"
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                icon={<Mail className="w-5 h-5" />}
                                placeholder="your@email.com"
                                required
                            />

                            <Input
                                label="Password"
                                type="password"
                                value={formData.password}
                                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                icon={<Lock className="w-5 h-5" />}
                                placeholder="••••••••"
                                required
                            />

                            <div className="flex justify-end">
                                <Link
                                    to="/forgot-password"
                                    className="text-sm font-medium text-primary-500 hover:text-primary-600 transition-colors"
                                >
                                    Forgot password?
                                </Link>
                            </div>

                            <Button
                                type="submit"
                                variant="primary"
                                className="w-full"
                                isLoading={isLoading}
                            >
                                Sign In
                            </Button>
                        </form>

                        <div className="relative">
                            <div className="absolute inset-0 flex items-center">
                                <span className="w-full border-t border-light-border dark:border-dark-border" />
                            </div>
                            <div className="relative flex justify-center text-xs uppercase">
                                <span className="bg-white dark:bg-[#151515] px-2 text-light-muted dark:text-dark-muted">
                                    Or continue with
                                </span>
                            </div>
                        </div>

                        <Button
                            type="button"
                            variant="outline"
                            className="w-full flex items-center justify-center gap-2 h-12"
                            onClick={handleGoogleLogin}
                            disabled={isLoading}
                        >
                            <svg className="h-5 w-5" viewBox="0 0 24 24">
                                <path
                                    d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                                    fill="#4285F4"
                                />
                                <path
                                    d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                                    fill="#34A853"
                                />
                                <path
                                    d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"
                                    fill="#FBBC05"
                                />
                                <path
                                    d="M12 5.38c1.62 0 3.06.56 4.21 1.66l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 12-4.53z"
                                    fill="#EA4335"
                                />
                            </svg>
                            Google
                        </Button>

                        <p className="text-center text-sm text-light-muted dark:text-dark-muted pt-2">
                            Don't have an account?{' '}
                            <Link
                                to="/register"
                                state={{ from: (location.state as any)?.from }}
                                className="text-primary-500 hover:text-primary-600 font-medium"
                            >
                                Sign Up
                            </Link>
                        </p>
                    </div>
                </CardContent>
            </Card>
        </motion.div>
    );
}

